window.QUESTION_BANK = [{"module": 1, "number": 1, "question": "<p>Which best describes Machine Learning according to the engineering-oriented definition?</p>", "options": [["A", "A computer follows manually programmed rules perfectly"], ["B", "Performance on a task improves through experience"], ["C", "A computer automatically becomes intelligent over time"], ["D", "A computer stores increasing amounts of data"]], "answers": ["B"], "multiple": false, "explanation": "<p>Mitchell's definition: performance $P$ on task $T$ improves through experience $E$.</p>"}, {"module": 1, "number": 2, "question": "<p>A house-price model has:</p>\n<ul>\n<li>historical house records</li>\n<li>task of predicting selling price</li>\n<li>mean prediction error</li>\n</ul>\n<p>What represents <strong>E</strong>?</p>", "options": [["A", "Predicting selling price"], ["B", "Historical house records"], ["C", "Mean prediction error"], ["D", "The prediction algorithm"]], "answers": ["B"], "multiple": false, "explanation": "<p>Experience = historical data.</p>"}, {"module": 1, "number": 3, "question": "<p>A bank wants to predict whether a transaction is <code>\"Fraud\"</code> or <code>\"Legitimate\"</code>.</p>\n<p>This is:</p>", "options": [["A", "Regression"], ["B", "Clustering"], ["C", "Classification"], ["D", "Reinforcement learning"]], "answers": ["C"], "multiple": false, "explanation": "<p>Fraud/Legitimate are categories.</p>"}, {"module": 1, "number": 4, "question": "<p>A property company predicts the selling price of a condominium in RM.</p>\n<p>This is:</p>", "options": [["A", "Classification"], ["B", "Regression"], ["C", "Clustering"], ["D", "Anomaly detection"]], "answers": ["B"], "multiple": false, "explanation": "<p>RM price is numerical.</p>"}, {"module": 1, "number": 5, "question": "<p>A retailer has customer transaction data but no predefined customer groups. An algorithm discovers four groups based on spending behaviour.</p>\n<p>This is:</p>", "options": [["A", "Classification"], ["B", "Regression"], ["C", "Clustering"], ["D", "Reinforcement learning"]], "answers": ["C"], "multiple": false, "explanation": "<p>No predefined labels; groups are discovered.</p>"}, {"module": 1, "number": 6, "question": "<p>Which problem is most clearly anomaly detection?</p>", "options": [["A", "Predict tomorrow's temperature"], ["B", "Identify suspicious transactions that differ from normal behaviour"], ["C", "Divide customers into spending groups"], ["D", "Predict whether a student will pass"]], "answers": ["B"], "multiple": false, "explanation": "<p>Anomalies are unusual patterns/events.</p>"}, {"module": 1, "number": 7, "question": "<p>Which is required for supervised learning?</p>", "options": [["A", "No historical data"], ["B", "Labels/known target outcomes"], ["C", "Rewards from an environment"], ["D", "Clusters must already exist"]], "answers": ["B"], "multiple": false, "explanation": "<p>Supervised learning uses labelled data.</p>"}, {"module": 1, "number": 8, "question": "<p>An AI plays a game, receives +10 when it wins and −10 when it loses, and adjusts its behaviour.</p>\n<p>This is:</p>", "options": [["A", "Supervised learning"], ["B", "Unsupervised learning"], ["C", "Reinforcement learning"], ["D", "Batch learning"]], "answers": ["C"], "multiple": false, "explanation": "<p>Learning through reward/punishment.</p>"}, {"module": 1, "number": 9, "question": "<p>Which statement about unsupervised learning is most accurate according to the lecture?</p>", "options": [["A", "It always predicts numerical values"], ["B", "It learns from labelled examples"], ["C", "It finds patterns or similarities in unlabelled data"], ["D", "It requires reward signals"]], "answers": ["C"], "multiple": false, "explanation": "<p>Unsupervised learning looks for structure in unlabelled data.</p>"}, {"module": 1, "number": 10, "question": "<p>A credit model is retrained every month using all newly collected data. Between retrainings, the model does not update itself.</p>\n<p>This is:</p>", "options": [["A", "Online learning"], ["B", "Batch learning"], ["C", "Reinforcement learning"], ["D", "Instance-based learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>Retrain periodically rather than incrementally.</p>"}, {"module": 1, "number": 11, "question": "<p>A model updates itself after receiving each new transaction.</p>\n<p>This is:</p>", "options": [["A", "Batch learning"], ["B", "Online learning"], ["C", "Model evaluation"], ["D", "KDD"]], "answers": ["B"], "multiple": false, "explanation": "<p>Model updates incrementally.</p>"}, {"module": 1, "number": 12, "question": "<p>A dataset is too large to fit into RAM. The algorithm loads part of the dataset, trains, then loads another part.</p>\n<p>This is:</p>", "options": [["A", "Clustering"], ["B", "Out-of-core learning"], ["C", "Underfitting"], ["D", "Instance-based learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>That's the lecture's definition of out-of-core learning.</p>"}, {"module": 1, "number": 13, "question": "<p>A new customer is classified based largely on the five most similar previous customers.</p>\n<p>This is:</p>", "options": [["A", "Model-based learning"], ["B", "Instance-based learning"], ["C", "Reinforcement learning"], ["D", "Batch learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>Prediction relies on similar stored instances.</p>"}, {"module": 1, "number": 14, "question": "<p>A model learns:</p>\n<div class=\"math-display\">$$\\text{Price} = 300(\\text{Size})+50000$$</div>\n<p>and uses this relationship for new houses.</p>\n<p>This is:</p>", "options": [["A", "Instance-based learning"], ["B", "Model-based learning"], ["C", "Unsupervised learning"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>A general relationship/model has been learned.</p>"}, {"module": 1, "number": 15, "question": "<p>Which result most strongly suggests <strong>overfitting</strong>?</p>", "options": [["A", "Training accuracy 60%, test accuracy 61%"], ["B", "Training accuracy 98%, test accuracy 65%"], ["C", "Training accuracy 90%, test accuracy 89%"], ["D", "Training accuracy 55%, test accuracy 50%"]], "answers": ["B"], "multiple": false, "explanation": "<p>Huge training-test gap.</p>"}, {"module": 1, "number": 16, "question": "<p>Which result most strongly suggests <strong>underfitting</strong>?</p>", "options": [["A", "Training accuracy 99%, test accuracy 60%"], ["B", "Training accuracy 94%, test accuracy 92%"], ["C", "Training accuracy 58%, test accuracy 56%"], ["D", "Training accuracy 100%, test accuracy 99%"]], "answers": ["C"], "multiple": false, "explanation": "<p>Poor even on training data indicates insufficient learning.</p>"}, {"module": 1, "number": 17, "question": "<p>Which is a possible solution to overfitting according to the lecture?</p>", "options": [["A", "Make the model more complicated"], ["B", "Add more irrelevant features"], ["C", "Gather more training data"], ["D", "Increase noise in the data"]], "answers": ["C"], "multiple": false, "explanation": "<p>More training data is one lecture-listed remedy.</p>"}, {"module": 1, "number": 18, "question": "<p>Which can help fix underfitting?</p>", "options": [["A", "Select a more powerful model"], ["B", "Reduce the amount of useful data"], ["C", "Add more constraints to the model"], ["D", "Remove useful features"]], "answers": ["A"], "multiple": false, "explanation": "<p>Underfitting can require a more powerful model.</p>"}, {"module": 1, "number": 19, "question": "<p>Why must training data be representative?</p>", "options": [["A", "It guarantees zero error"], ["B", "The model must generalize to future observations similar to the target population"], ["C", "It allows all algorithms to become supervised"], ["D", "It removes the need for testing"]], "answers": ["B"], "multiple": false, "explanation": "<p>Training data should represent the cases you want to generalize to.</p>"}, {"module": 1, "number": 20, "question": "<p>A dataset contains:</p>\n<pre><code class=\"language-text\">Age = 220\nHeight = 8.7 metres\nIncome = missing\n</code></pre>\n<p>The major problem is:</p>", "options": [["A", "Reinforcement learning"], ["B", "Poor-quality/noisy data"], ["C", "Online learning"], ["D", "Underfitting"]], "answers": ["B"], "multiple": false, "explanation": "<p>Errors, missing data, outliers, noise.</p>"}, {"module": 1, "number": 21, "question": "<p>Creating:</p>\n<div class=\"math-display\">$$\\text{DebtToIncome}=\\frac{\\text{Debt}}{\\text{Income}}$$</div>\n<p>from existing variables is an example of:</p>", "options": [["A", "Deployment"], ["B", "Feature engineering"], ["C", "Reinforcement learning"], ["D", "Clustering"]], "answers": ["B"], "multiple": false, "explanation": "<p>Creating a more useful feature.</p>"}, {"module": 1, "number": 22, "question": "<p>Which CRISP-DM phase comes first?</p>", "options": [["A", "Modeling"], ["B", "Evaluation"], ["C", "Business Understanding"], ["D", "Data Preparation"]], "answers": ["C"], "multiple": false, "explanation": "<p>CRISP-DM begins with Business Understanding.</p>"}, {"module": 1, "number": 23, "question": "<p>Which framework explicitly begins with <strong>Business Understanding</strong> and includes <strong>Deployment</strong>?</p>", "options": [["A", "KDD"], ["B", "SEMMA"], ["C", "CRISP-DM"], ["D", "K-Means"]], "answers": ["C"], "multiple": false, "explanation": "<p>That's the major distinguishing feature of CRISP-DM here.</p>"}, {"module": 1, "number": 24, "question": "<p>Which correctly represents SEMMA?</p>", "options": [["A", "Sample → Explore → Modify → Model → Assess"], ["B", "Select → Evaluate → Modify → Mine → Analyze"], ["C", "Study → Explore → Model → Measure → Apply"], ["D", "Sample → Evaluate → Mine → Modify → Analyze"]], "answers": ["A"], "multiple": false, "explanation": "<p>SEMMA = Sample, Explore, Modify, Model, Assess.</p>"}, {"module": 1, "number": 25, "question": "<p>Which is the correct broad idea behind KDD?</p>", "options": [["A", "Reward → action → reinforcement"], ["B", "Data → selection/preprocessing/transformation/mining/evaluation → knowledge"], ["C", "Data → neural network only"], ["D", "Business objective → reinforcement → deployment"]], "answers": ["B"], "multiple": false, "explanation": "<p>KDD structures the journey from raw data to knowledge.</p>"}, {"module": 1, "number": 26, "question": "<p>A spam classifier is trained once using one million labelled emails. It then immediately classifies every incoming email but never updates its parameters until next month's retraining.</p>\n<p>Which description is most accurate?</p>", "options": [["A", "Online supervised learning"], ["B", "Batch supervised learning"], ["C", "Online unsupervised learning"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>This is a good trap.</p>\n<p>It makes <strong>real-time predictions</strong>, but it does <strong>not learn online</strong>.</p>"}, {"module": 1, "number": 27, "question": "<p>A company gives an algorithm customer data with no customer segment labels. The algorithm discovers three clusters. Managers then name the groups <code>\"Budget\"</code>, <code>\"Regular\"</code>, and <code>\"Premium\"</code>.</p>\n<p>What learning happened?</p>", "options": [["A", "Supervised classification"], ["B", "Unsupervised clustering"], ["C", "Regression"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>The humans naming clusters afterward does not magically make the original learning supervised.</p>"}, {"module": 1, "number": 28, "question": "<p>A model obtains:</p>\n<pre><code class=\"language-text\">Training error = 40%\nTest error = 42%\n</code></pre>\n<p>Which interpretation is strongest?</p>", "options": [["A", "Severe overfitting"], ["B", "Likely underfitting"], ["C", "Excellent generalization"], ["D", "Data leakage"]], "answers": ["B"], "multiple": false, "explanation": "<p>The training performance itself is poor.</p>\n<p>The model isn't even learning the known data adequately.</p>"}, {"module": 1, "number": 29, "question": "<p>A model obtains:</p>\n<pre><code class=\"language-text\">Training error = 1%\nTest error = 24%\n</code></pre>\n<p>Which interpretation is strongest?</p>", "options": [["A", "Underfitting"], ["B", "Overfitting"], ["C", "Clustering"], ["D", "Out-of-core learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>Low training error + much higher test error = classic overfitting.</p>"}, {"module": 1, "number": 30, "question": "<p>A hospital collects 2 million patient records, but every patient comes from the same specialist cardiac clinic. The model is deployed to predict outcomes for the entire population.</p>\n<p>What is the most obvious concern?</p>", "options": [["A", "Dataset is too small"], ["B", "Training data may be nonrepresentative"], ["C", "Online learning is impossible"], ["D", "Model must use reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>More data is not automatically better if the population is biased.</p>\n<p>The lecture emphasizes that training data should represent the new cases the model is expected to generalize to.</p>"}, {"module": 1, "number": 31, "question": "<p>A team begins by asking:</p>\n<blockquote>\n<p>What business objective are we trying to achieve?</p>\n</blockquote>\n<p>Which framework most explicitly emphasizes this as its first phase?</p>", "options": [["A", "SEMMA"], ["B", "KDD"], ["C", "CRISP-DM"], ["D", "Online learning"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 1, "number": 32, "question": "<p>Which stage belongs to SEMMA but not as a named CRISP-DM phase?</p>", "options": [["A", "Sample"], ["B", "Modeling"], ["C", "Evaluation"], ["D", "Data Preparation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 1, "number": 33, "question": "<p>Which one ends with an explicit <strong>Deployment</strong> phase in the lecture?</p>", "options": [["A", "KDD"], ["B", "SEMMA"], ["C", "CRISP-DM"], ["D", "All three"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 1, "question": "<p>A company says:</p>\n<blockquote>\n<p>“We want to reduce unexpected equipment downtime.”</p>\n</blockquote>\n<p>Which CRISP-DM phase handles this first?</p>", "options": [["A", "Modeling"], ["B", "Business Understanding"], ["C", "Data Preparation"], ["D", "Deployment"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 2, "question": "<p>The business goal is converted into:</p>\n<blockquote>\n<p>“Predict equipment failure within the next 24 hours.”</p>\n</blockquote>\n<p>This is primarily part of:</p>", "options": [["A", "Business Understanding"], ["B", "Data Cleaning"], ["C", "Feature Scaling"], ["D", "Deployment"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 3, "question": "<p>A data scientist investigates available sensor logs, missing values and whether the data is relevant.</p>\n<p>Which phase?</p>", "options": [["A", "Modeling"], ["B", "Deployment"], ["C", "Data Understanding"], ["D", "Evaluation"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 4, "question": "<p>Encoding categories, handling missing values and scaling numeric features belongs mainly to:</p>", "options": [["A", "Data Preparation"], ["B", "Business Understanding"], ["C", "Deployment"], ["D", "Evaluation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 5, "question": "<p>Which phase asks:</p>\n<blockquote>\n<p>“Does the model satisfy the business criteria defined earlier?”</p>\n</blockquote>", "options": [["A", "Modeling"], ["B", "Evaluation"], ["C", "Data Understanding"], ["D", "Data Retrieval"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 6, "question": "<p>Which statement is most accurate?</p>", "options": [["A", "CRISP-DM and ML Pipeline are exactly the same"], ["B", "CRISP-DM is mainly code"], ["C", "ML Pipeline is more technically focused"], ["D", "CRISP-DM begins with feature scaling"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 7, "question": "<p>Which sequence is correct?</p>", "options": [["A", "Modeling → Business Understanding → Deployment"], ["B", "Business Understanding → Data Understanding → Data Preparation"], ["C", "Deployment → Modeling → Evaluation"], ["D", "Data Preparation → Business Understanding → Modeling"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 8, "question": "<p>Which is typically one of the heaviest stages according to the lecture?</p>", "options": [["A", "Data Preparation"], ["B", "Deployment"], ["C", "Business Understanding"], ["D", "Evaluation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 9, "question": "<p>Which format is naturally tabular and generally convenient for pandas?</p>", "options": [["A", "JSON"], ["B", "CSV"], ["C", "XML"], ["D", "HTML"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 10, "question": "<p>Which format commonly contains nested key-value pairs?</p>", "options": [["A", "CSV"], ["B", "SQL"], ["C", "JSON"], ["D", "TXT"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 11, "question": "<p>Which format is tag-based and commonly associated with legacy enterprise systems?</p>", "options": [["A", "XML"], ["B", "CSV"], ["C", "JSON"], ["D", "SQL"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 12, "question": "<p>Which is most closely associated with relational tables and enterprise databases?</p>", "options": [["A", "HTML"], ["B", "SQL"], ["C", "JSON"], ["D", "CSV"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 13, "question": "<p>Why may JSON require additional preprocessing before classical ML?</p>", "options": [["A", "It is always encrypted"], ["B", "It is hierarchical and may need flattening"], ["C", "It cannot contain numbers"], ["D", "It contains only images"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 14, "question": "<p>Web scraping broadly involves:</p>\n<div class=\"math-display\">$$\\text{Crawl} \\rightarrow \\text{Scrape}$$</div>\n<p><strong>Crawl:</strong> obtain webpages.</p>\n<p><strong>Scrape:</strong> extract desired information.</p>\n<p>Which step retrieves webpages from URLs?</p>", "options": [["A", "Scraping"], ["B", "Crawling"], ["C", "Scaling"], ["D", "Encoding"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 15, "question": "<p>Which step extracts specific information from retrieved HTML?</p>", "options": [["A", "Scraping"], ["B", "Crawling"], ["C", "Modeling"], ["D", "Binning"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 16, "question": "<p>Which feature is categorical?</p>", "options": [["A", "Age = 21"], ["B", "Price = 99.90"], ["C", "Colour = Red"], ["D", "Height = 181"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 17, "question": "<p>Which is the most likely preprocessing for:</p>\n<pre><code class=\"language-text\">Colour = Red / Blue / Green\n</code></pre>", "options": [["A", "Scaling"], ["B", "Categorical encoding"], ["C", "Tokenization"], ["D", "Date extraction"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 18, "question": "<p>Which is most appropriate for a datetime feature?</p>", "options": [["A", "Extract month/day/hour"], ["B", "Always one-hot encode every individual timestamp"], ["C", "Remove it automatically"], ["D", "Apply TF-IDF"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 19, "question": "<p>Which preprocessing is most closely associated with natural-language text?</p>", "options": [["A", "Tokenization"], ["B", "Min-Max scaling only"], ["C", "SQL join"], ["D", "Forward fill only"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 20, "question": "<p>Which function is best for seeing column data types?</p>", "options": [["A", "<code>df.describe()</code>"], ["B", "<code>df.info()</code>"], ["C", "<code>df.groupby()</code>"], ["D", "<code>df.dropna()</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 21, "question": "<p>Which function gives mean, standard deviation, min and max?</p>", "options": [["A", "<code>df.info()</code>"], ["B", "<code>df.describe()</code>"], ["C", "<code>df.ffill()</code>"], ["D", "<code>df.rename()</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 22, "question": "<p>Suppose a column contains 1000 rows but <code>df.info()</code> reports 940 non-null values.</p>\n<p>How many values are missing?</p>", "options": [["A", "40"], ["B", "60"], ["C", "940"], ["D", "1000"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 23, "question": "<p>The lecture presents three broad strategies:</p>\n<div class=\"math-display\">$$\\text{Remove}$$</div>\n<div class=\"math-display\">$$\\text{Impute}$$</div>\n<div class=\"math-display\">$$\\text{Forward/Backward fill}$$</div>\n<p>What does this do?</p>\n<pre><code class=\"language-python\">df.dropna()\n</code></pre>", "options": [["A", "Replaces missing values"], ["B", "Removes observations containing missing values"], ["C", "Finds duplicate records"], ["D", "Converts values to numeric"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 24, "question": "<p>What does this do?</p>\n<pre><code class=\"language-python\">df[&quot;price&quot;].fillna(df[&quot;price&quot;].mean())\n</code></pre>", "options": [["A", "Removes price"], ["B", "Replaces missing prices with mean price"], ["C", "Calculates median"], ["D", "Removes duplicates"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 25, "question": "<p>When is median often preferable to mean for numerical imputation?</p>", "options": [["A", "Strong outliers exist"], ["B", "No missing values exist"], ["C", "The feature is text"], ["D", "The data contains only categories"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 26, "question": "<p>For the values:</p>\n<pre><code class=\"language-text\">100\n110\n120\n1000\nNaN\n</code></pre>\n<p>which central tendency is less affected by <code>1000</code>?</p>", "options": [["A", "Mean"], ["B", "Median"], ["C", "Variance"], ["D", "Range"]], "answers": ["B"], "multiple": false, "explanation": "<p>Because the extreme value pulls the mean upward.</p>"}, {"module": 2, "number": 27, "question": "<p>Which missing-value strategy is particularly reasonable for ordered/time-series data when the previous state tends to persist?</p>", "options": [["A", "One-hot encoding"], ["B", "Forward fill"], ["C", "TF-IDF"], ["D", "Standardization"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 28, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df.ffill()\n</code></pre>\n<p>do?</p>", "options": [["A", "Copies the next known value backward"], ["B", "Copies the previous known value forward"], ["C", "Deletes all missing rows"], ["D", "Converts values to float"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 29, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df.bfill()\n</code></pre>\n<p>do?</p>", "options": [["A", "Uses the following observation to fill a missing value"], ["B", "Uses the previous observation"], ["C", "Binarizes the column"], ["D", "Removes outliers"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 30, "question": "<p>Which command counts duplicated rows?</p>\n<pre><code class=\"language-python\">?\n</code></pre>", "options": [["A", "<code>df.isna().sum()</code>"], ["B", "<code>df.duplicated().sum()</code>"], ["C", "<code>df.describe()</code>"], ["D", "<code>df.groupby()</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 31, "question": "<p>Which removes exact duplicates?</p>", "options": [["A", "<code>df.drop_duplicates()</code>"], ["B", "<code>df.dropna()</code>"], ["C", "<code>df.ffill()</code>"], ["D", "<code>df.to_numeric()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 32, "question": "<p>Why should duplicates not always be automatically removed?</p>", "options": [["A", "Pandas cannot remove them"], ["B", "Some apparently identical records may represent genuine repeated events"], ["C", "Duplicate rows are required for regression"], ["D", "Duplicates improve model accuracy"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 33, "question": "<p>A column contains:</p>\n<pre><code class=\"language-text\">&quot;2026-10-03&quot;\n</code></pre>\n<p>but pandas stores it as <code>object</code>.</p>\n<p>Which function is appropriate?</p>", "options": [["A", "<code>pd.to_datetime()</code>"], ["B", "<code>pd.get_dummies()</code>"], ["C", "<code>df.groupby()</code>"], ["D", "<code>df.drop_duplicates()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 34, "question": "<p>A column contains:</p>\n<pre><code class=\"language-text\">&quot;150.00&quot;\n</code></pre>\n<p>as text but should be numeric.</p>\n<p>Which function is appropriate?</p>", "options": [["A", "<code>pd.to_numeric()</code>"], ["B", "<code>pd.to_datetime()</code>"], ["C", "<code>pd.qcut()</code>"], ["D", "<code>pd.concat()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 35, "question": "<p>Know the conceptual distinction:</p>\n<div class=\"math-display\">$$\\text{Column Selection}\n=\n\\text{Which variables}?$$</div>\n<div class=\"math-display\">$$\\text{Row Filtering}\n=\n\\text{Which observations}?$$</div>\n<p>What does:</p>\n<pre><code class=\"language-python\">df[&quot;price&quot;]\n</code></pre>\n<p>do?</p>", "options": [["A", "Selects the <code>price</code> column"], ["B", "Selects the first row"], ["C", "Removes the price column"], ["D", "Calculates average price"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 36, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df[df[&quot;price&quot;] &gt; 100]\n</code></pre>\n<p>do?</p>", "options": [["A", "Keeps rows where price exceeds 100"], ["B", "Replaces prices below 100"], ["C", "Sorts by price"], ["D", "Selects only the column name"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 37, "question": "<p>What does <code>iloc</code> mainly select by?</p>", "options": [["A", "Column labels only"], ["B", "Integer position"], ["C", "Data type"], ["D", "Missing-value count"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 38, "question": "<p>Which is feature engineering?</p>", "options": [["A", "Delete the whole dataset"], ["B", "Extract <code>month</code> from a timestamp"], ["C", "Install pandas"], ["D", "Save a CSV"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 39, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df[&quot;purchase_month&quot;] = df[&quot;date&quot;].dt.month\n</code></pre>\n<p>create?</p>", "options": [["A", "Missing values"], ["B", "A derived feature"], ["C", "A duplicate"], ["D", "A database table"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 40, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df[&quot;is_weekend&quot;] = df[&quot;date&quot;].dt.dayofweek &gt; 4\n</code></pre>\n<p>produce?</p>", "options": [["A", "A Boolean weekend feature"], ["B", "A price category"], ["C", "A text token"], ["D", "A standardized score"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 41, "question": "<p>Which method is generally better for <strong>nominal</strong> categories such as colour?</p>", "options": [["A", "Arbitrary integer codes"], ["B", "One-hot encoding"], ["C", "Log transformation"], ["D", "Mean imputation"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 42, "question": "<p>Why may this be dangerous?</p>\n<pre><code class=\"language-text\">Malaysia = 1\nJapan = 2\nBrazil = 3\n</code></pre>", "options": [["A", "Computers cannot process integers"], ["B", "The model may interpret the numbers as meaningful order/magnitude"], ["C", "It always produces missing values"], ["D", "It creates a datetime"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 43, "question": "<p>Which representation avoids implied order?</p>", "options": [["A", "<pre><code class=\"language-text\">Red = 1\nBlue = 2\nGreen = 3\n</code></pre>"], ["B", "<pre><code class=\"language-text\">Red   = [1,0,0]\nBlue  = [0,1,0]\nGreen = [0,0,1]\n</code></pre>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 44, "question": "<p>Which pandas function can perform one-hot encoding?</p>", "options": [["A", "<code>pd.get_dummies()</code>"], ["B", "<code>pd.to_datetime()</code>"], ["C", "<code>df.dropna()</code>"], ["D", "<code>df.info()</code>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 45, "question": "<p>Why is feature scaling especially important for distance-based algorithms?</p>", "options": [["A", "Large-scale variables can dominate distance calculations"], ["B", "It creates labels automatically"], ["C", "It removes all outliers"], ["D", "It converts text into images"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 46, "question": "<p>Which transformation usually maps values into approximately:</p>\n<div class=\"math-display\">$$[0,1]$$</div>", "options": [["A", "Standardization"], ["B", "Min-Max scaling"], ["C", "One-hot encoding"], ["D", "TF-IDF"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 47, "question": "<p>Standardization generally transforms a feature toward:</p>\n<div class=\"math-display\">$$\\text{Mean}=0$$</div>\n<p>and:</p>\n<div class=\"math-display\">$$\\text{StandardDeviation}=1$$</div>\n<p>True or False?</p>", "options": [["A", "True"], ["B", "False"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture contrasts Min-Max scaling with Z-score standardization this way.</p>"}, {"module": 2, "number": 48, "question": "<p>Suppose:</p>\n<div class=\"math-display\">$$\\text{min}=20$$</div>\n<div class=\"math-display\">$$\\text{max}=40$$</div>\n<p>and:</p>\n<div class=\"math-display\">$$x=30$$</div>\n<p>Using Min-Max:</p>\n<div class=\"math-display\">$$x'=\n\\frac{x-\\text{min}}{\\text{max}-\\text{min}}$$</div>\n<div class=\"math-display\">$$=\n\\frac{30-20}{40-20}\n=\n\\frac{10}{20}\n=\n0.5$$</div>\n<p>So:</p>\n<p>Min-Max scaled value of 30 is:</p>", "options": [["A", "0"], ["B", "0.25"], ["C", "0.5"], ["D", "1"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 2, "number": 49, "question": "<p>Lecture 2 only introduces the basics; don't turn this into Lecture 3–4 unnecessarily.</p>\n<p>Know:</p>\n<pre><code class=\"language-text\">Tokenization\nStopword removal\nStemming/Lemmatization\n</code></pre>\n<p>The lecture's example changes:</p>\n<pre><code class=\"language-text\">&quot;The cats are running!&quot;\n</code></pre>\n<p>into roughly:</p>\n<pre><code class=\"language-text\">[&quot;cat&quot;, &quot;run&quot;]\n</code></pre>\n<p>Tokenization means:</p>", "options": [["A", "Scale numbers"], ["B", "Split text into units such as words"], ["C", "Remove duplicates"], ["D", "Create SQL tables"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 50, "question": "<p>Stopwords are:</p>", "options": [["A", "Always-important keywords"], ["B", "Common terms that often carry little useful information"], ["C", "Missing values"], ["D", "Numeric outliers"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 51, "question": "<p>Which best describes stemming/lemmatization?</p>", "options": [["A", "Turn text into images"], ["B", "Reduce related word forms toward a root/canonical form"], ["C", "Remove rows"], ["D", "Detect duplicates"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 52, "question": "<p>What does this calculate?</p>\n<pre><code class=\"language-python\">df.groupby(&quot;user_type&quot;)[&quot;price&quot;].mean()\n</code></pre>", "options": [["A", "Overall price maximum"], ["B", "Mean price for each user type"], ["C", "Number of missing prices"], ["D", "Removes user types"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 53, "question": "<p>What is the conceptual process of <code>groupby()</code>?</p>", "options": [["A", "Train-Test-Evaluate"], ["B", "Split-Apply-Combine"], ["C", "Encode-Scale-Deploy"], ["D", "Crawl-Scrape-Store"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 54, "question": "<p>What does:</p>\n<pre><code class=\"language-python\">df.groupby(&quot;user_type&quot;)[&quot;quantity&quot;].sum()\n</code></pre>\n<p>calculate?</p>", "options": [["A", "Total quantity for each user type"], ["B", "Mean user type"], ["C", "Number of columns"], ["D", "Maximum date"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 55, "question": "<p>You want to show monthly revenue from January to December.</p>", "options": [["A", "Histogram"], ["B", "Line chart"], ["C", "Box plot"], ["D", "Pie chart"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 56, "question": "<p>You want to compare sales across:</p>\n<pre><code class=\"language-text\">KL\nPenang\nIpoh\nJohor\n</code></pre>", "options": [["A", "Bar chart"], ["B", "Histogram"], ["C", "Scatter"], ["D", "Line only"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 57, "question": "<p>You want to see the distribution of employee salaries.</p>", "options": [["A", "Histogram"], ["B", "Line"], ["C", "Scatter"], ["D", "Pie"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 58, "question": "<p>You want to identify potential outliers in salary.</p>", "options": [["A", "Line"], ["B", "Box plot"], ["C", "Pie"], ["D", "Map"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 59, "question": "<p>You want to investigate:</p>\n<div class=\"math-display\">$$\\text{AdvertisingSpend}$$</div>\n<p>versus:</p>\n<div class=\"math-display\">$$\\text{Sales}$$</div>", "options": [["A", "Scatter plot"], ["B", "Histogram"], ["C", "Pie chart"], ["D", "Bar chart only"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 60, "question": "<p>A scientist computes Min-Max scaling parameters using both training and test data before training.</p>\n<p>What is the main problem?</p>", "options": [["A", "Overfitting only"], ["B", "Data leakage"], ["C", "Underfitting"], ["D", "Clustering"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 61, "question": "<p>What is the correct approach?</p>", "options": [["A", "<pre><code class=\"language-python\">scaler.fit(X_train)\nX_train = scaler.transform(X_train)\nX_test = scaler.transform(X_test)\n</code></pre>"], ["B", "<pre><code class=\"language-python\">scaler.fit(X_train)\nscaler.fit(X_test)\n</code></pre>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 62, "question": "<p>Why shouldn't you refit preprocessing independently on test/new data?</p>", "options": [["A", "The model expects transformations consistent with training"], ["B", "Pandas prohibits it"], ["C", "Test data cannot contain numbers"], ["D", "It automatically causes duplicates"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture's “Crucial Rule” is that deployment data must go through the <strong>same preprocessing</strong> learned during training.</p>"}, {"module": 2, "number": 63, "question": "<p>A dataset has:</p>\n<pre><code class=\"language-text\">Age        25\nIncome     85000\nCountry    Malaysia\nSignup     2026-01-05\n</code></pre>\n<p>Which combination is most reasonable?</p>", "options": [["A", "TF-IDF Age, histogram Country"], ["B", "Scale Age/Income where needed, encode Country, derive features from Signup"], ["C", "Convert everything to strings"], ["D", "Remove all non-numeric columns"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 64, "question": "<p>A model uses KNN with:</p>\n<pre><code class=\"language-text\">Age: 20–70\nIncome: 20,000–500,000\n</code></pre>\n<p>What should you be most concerned about?</p>", "options": [["A", "Income may dominate the distance calculation"], ["B", "Age becomes text"], ["C", "KNN requires XML"], ["D", "One-hot encoding income"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 65, "question": "<p>A categorical feature contains:</p>\n<pre><code class=\"language-text\">Red\nBlue\nGreen\n</code></pre>\n<p>Someone maps:</p>\n<pre><code class=\"language-text\">Red=1\nBlue=2\nGreen=3\n</code></pre>\n<p>What is the primary concern?</p>", "options": [["A", "Data becomes too small"], ["B", "False ordinal/magnitude relationship"], ["C", "Cannot calculate accuracy"], ["D", "Causes missing values"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 66, "question": "<p>A time-series sensor reading is:</p>\n<pre><code class=\"language-text\">10:00  72\n10:01  NaN\n10:02  73\n</code></pre>\n<p>If the sensor value changes slowly and nearby state reasonably persists, which option may be sensible?</p>", "options": [["A", "One-hot encoding"], ["B", "Forward fill"], ["C", "TF-IDF"], ["D", "SQL join"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 2, "number": 67, "question": "<p>You want to investigate whether transaction amount increases as customer age increases.</p>\n<p>Which visualization?</p>", "options": [["A", "Scatter"], ["B", "Histogram"], ["C", "Bar"], ["D", "Pie"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 2, "number": 68, "question": "<p>You want to understand whether salary contains extreme observations before choosing mean imputation.</p>\n<p>Which visualization is especially useful?</p>", "options": [["A", "Box plot"], ["B", "Line chart"], ["C", "Pie chart"], ["D", "Area chart"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 1, "question": "<p>What is the main purpose of feature engineering?</p>", "options": [["A", "Increase the number of rows"], ["B", "Transform raw data into useful representations for ML"], ["C", "Always remove categorical features"], ["D", "Replace model evaluation"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 2, "question": "<p>Which statement is most consistent with the lecture?</p>", "options": [["A", "Complex algorithms always outperform simple algorithms"], ["B", "Feature engineering is performed only once"], ["C", "Good features can be more important than using a more complex algorithm"], ["D", "Raw data should never be transformed"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 3, "question": "<p>Which sequence best reflects the iterative feature-engineering process?</p>", "options": [["A", "Engineer → Train → Evaluate → Refine"], ["B", "Deploy → Delete → Encode → Train"], ["C", "Evaluate → Collect → Stop"], ["D", "Scale → Deploy → Ignore performance"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 4, "question": "<p>Why is domain knowledge important?</p>", "options": [["A", "It automatically removes all missing data"], ["B", "It helps identify transformations that make sense for the actual problem"], ["C", "It makes test data unnecessary"], ["D", "It replaces mathematics entirely"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 5, "question": "<p>A music recommendation system only needs to know whether a user has ever listened to a song.</p>\n<p>Which transformation is most suitable?</p>", "options": [["A", "Log transformation"], ["B", "Binarization"], ["C", "Dummy coding"], ["D", "TF-IDF"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 6, "question": "<p>Given:</p>\n<pre><code class=\"language-text\">listen_count = [0, 14, 0, 37, 2]\n</code></pre>\n<p>using threshold $&gt;0$, what is the binary result?</p>", "options": [["A", "<code>[0, 14, 0, 37, 2]</code>"], ["B", "<code>[0, 1, 0, 1, 1]</code>"], ["C", "<code>[1, 0, 1, 0, 0]</code>"], ["D", "<code>[0, 0, 0, 1, 1]</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 7, "question": "<p>A sensor outputs:</p>\n<div class=\"math-display\">$$87.638294\\%$$</div>\n<p>but precision beyond the nearest whole percentage is meaningless.</p>\n<p>Which transformation is most appropriate?</p>", "options": [["A", "Binarization"], ["B", "Rounding"], ["C", "One-hot encoding"], ["D", "Hashing"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 8, "question": "<p>Why might excessive decimal precision be harmful?</p>", "options": [["A", "It may represent noise rather than meaningful signal"], ["B", "Decimals cannot be processed by ML"], ["C", "All decimals indicate missing data"], ["D", "It forces unsupervised learning"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 9, "question": "<p>Suppose model performance depends not just on Attack and Defense separately, but on having both high simultaneously.</p>\n<p>Which feature could help?</p>", "options": [["A", "<div class=\"math-display\">$$\\text{Attack}+0$$</div>"], ["B", "<div class=\"math-display\">$$\\text{Attack} \\times \\text{Defense}$$</div>"], ["C", "One-hot encode Attack"], ["D", "Drop Defense"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture uses exactly the interaction:</p>\n<div class=\"math-display\">$$49\\times49=2401$$</div>\n<p>to demonstrate this idea.</p>"}, {"module": 3, "number": 10, "question": "<p>Why create interaction features?</p>", "options": [["A", "To capture relationships between variables that may not be visible when treated independently"], ["B", "To reduce every feature to 0/1"], ["C", "To remove categorical variables"], ["D", "To prevent test/train splitting"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 11, "question": "<p>Given:</p>\n<div class=\"math-display\">$$x_1,\\ x_2$$</div>\n<p>a degree-2 expansion may create:</p>\n<div class=\"math-display\">$$x_1,\\ x_2,\\ x_1^2,\\ x_1x_2,\\ x_2^2$$</div>\n<p>What is a major danger of blindly applying polynomial features to many original columns?</p>", "options": [["A", "Data becomes XML"], ["B", "Feature explosion"], ["C", "Categories become ordinal"], ["D", "Missing values disappear"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture explicitly warns about feature explosion when polynomial expansion is applied to many columns.</p>"}, {"module": 3, "number": 12, "question": "<p>Transforming:</p>\n<div class=\"math-display\">$$\\text{Age}=37$$</div>\n<p>into:</p>\n<pre><code class=\"language-text\">30–39\n</code></pre>\n<p>is called:</p>", "options": [["A", "Scaling"], ["B", "Binning"], ["C", "Stemming"], ["D", "Hashing"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 13, "question": "<p>Which best describes fixed-width bins?</p>", "options": [["A", "Each bin contains equal numbers of observations"], ["B", "Each bin covers equal numerical width"], ["C", "Boundaries are learned only by CNNs"], ["D", "Every value becomes 0 or 1"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 14, "question": "<p>Which is fixed-width?</p>", "options": [["A", "<pre><code class=\"language-text\">0–9\n10–19\n20–29\n30–39\n</code></pre>"], ["B", "<pre><code class=\"language-text\">Lowest 25%\nNext 25%\nNext 25%\nTop 25%\n</code></pre>"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture defines fixed-width binning as predefined ranges of equal or deliberately fixed numerical width.</p>"}, {"module": 3, "number": 15, "question": "<p>Suppose a developer-age feature is transformed as:</p>\n<pre><code class=\"language-text\">0–22   Student\n22–35  Junior\n35–50  Senior\n50–100 Veteran\n</code></pre>\n<p>This is best described as:</p>", "options": [["A", "Quantile binning"], ["B", "Custom/domain-based binning"], ["C", "One-hot encoding"], ["D", "Standardization"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 16, "question": "<p>Why can custom bins be preferable to equal-width bins?</p>", "options": [["A", "They can reflect meaningful business or domain boundaries"], ["B", "They always guarantee equal group sizes"], ["C", "They eliminate missing values"], ["D", "They convert data to text automatically"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 17, "question": "<p>What does quartile binning attempt to produce?</p>", "options": [["A", "Four bins of equal numerical width"], ["B", "Four bins containing approximately 25% of the observations each"], ["C", "Four random bins"], ["D", "Four one-hot columns"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 18, "question": "<p>When is quantile binning especially useful?</p>", "options": [["A", "Highly uneven/skewed distributions"], ["B", "Pure image data only"], ["C", "When every value is identical"], ["D", "When categories already have an order"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 19, "question": "<p>Which situation most strongly suggests considering a log transformation?</p>", "options": [["A", "Country = Malaysia/Japan/UK"], ["B", "Income distribution with a long right tail and a few extremely large values"], ["C", "Colour categories"], ["D", "Missing text"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 20, "question": "<p>What is the major effect of the log transformation?</p>", "options": [["A", "Expands large values even more"], ["B", "Compresses large values and reduces right skew"], ["C", "Converts categories to binary"], ["D", "Sorts records alphabetically"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 21, "question": "<p>What is Box-Cox primarily intended to do?</p>", "options": [["A", "Encode nominal features"], ["B", "Find a useful power transformation that stabilizes variance and makes the distribution more normal-like"], ["C", "Detect duplicates"], ["D", "Generate images"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 22, "question": "<p>What important restriction does the lecture give for Box-Cox?</p>", "options": [["A", "<div class=\"math-display\">$$x&lt;0$$</div>"], ["B", "<div class=\"math-display\">$$x&gt;0$$</div>"], ["C", "Only integer data"], ["D", "Only categorical data"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture notes that Box-Cox searches for a parameter $\\lambda$ and requires strictly positive values.</p>"}, {"module": 3, "number": 23, "question": "<p>Which is nominal?</p>", "options": [["A", "Small, Medium, Large"], ["B", "Primary, Secondary, University"], ["C", "Red, Blue, Green"], ["D", "Low, Medium, High"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 24, "question": "<p>Which is ordinal?</p>", "options": [["A", "Malaysia, Japan, Brazil"], ["B", "Cat, Dog, Horse"], ["C", "Small, Medium, Large"], ["D", "Red, Blue, Green"]], "answers": ["C"], "multiple": false, "explanation": "<p>Nominal categories have no meaningful ordering, while ordinal categories do.</p>"}, {"module": 3, "number": 25, "question": "<p>Suppose:</p>\n<pre><code class=\"language-text\">Action    = 0\nAdventure = 1\nSports    = 2\n</code></pre>\n<p>What is the main danger if these are nominal categories?</p>", "options": [["A", "<p>Model may interpret:</p>\n<div class=\"math-display\">$$\\text{Sports} &gt; \\text{Adventure} &gt; \\text{Action}$$</div>"], ["B", "Model cannot process integers"], ["C", "Values become missing"], ["D", "Dataset becomes too small"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture explicitly warns that numeric labels introduce false magnitude/order when used with nominal categories.</p>"}, {"module": 3, "number": 26, "question": "<p>One-hot encoding of:</p>\n<pre><code class=\"language-text\">Red\nBlue\nGreen\n</code></pre>\n<p>could represent Red as:</p>", "options": [["A", "<code>0</code>"], ["B", "<code>3</code>"], ["C", "<code>[1,0,0]</code>"], ["D", "<code>[1,1,1]</code>"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 27, "question": "<p>With $m$ categories, standard one-hot encoding creates:</p>", "options": [["A", "1 feature"], ["B", "$m-1$ features"], ["C", "$m$ binary features"], ["D", "$2m$ features"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 3, "number": 28, "question": "<p>If a variable has 5 categories, dummy coding normally creates:</p>", "options": [["A", "5 columns"], ["B", "4 columns"], ["C", "1 column"], ["D", "10 columns"]], "answers": ["B"], "multiple": false, "explanation": "<div class=\"math-display\">$$m-1=5-1=4$$</div>"}, {"module": 3, "number": 29, "question": "<p>Why is one category dropped in dummy coding?</p>", "options": [["A", "To provide a reference category and avoid redundant representation in some models"], ["B", "Because the category is invalid"], ["C", "Because pandas cannot store it"], ["D", "To remove missing values"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 30, "question": "<p>How does effect coding differ from dummy coding according to the lecture?</p>", "options": [["A", "The reference category is represented using −1 rather than all zeros"], ["B", "It produces images"], ["C", "It creates $m$ columns"], ["D", "It uses TF-IDF"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 3, "number": 31, "question": "<p>A categorical feature has 100,000 unique product IDs.</p>\n<p>Which technique may reduce dimensionality to a fixed number of columns?</p>", "options": [["A", "One-hot only"], ["B", "Feature hashing"], ["C", "Log transform"], ["D", "Quantile binning"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 3, "number": 32, "question": "<p>What is the major trade-off of feature hashing?</p>", "options": [["A", "Hash collisions"], ["B", "Mandatory missing values"], ["C", "It cannot handle categories"], ["D", "Every category gets its own column"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 1, "question": "<p>What does tokenization do?</p>", "options": [["A", "Scales numbers"], ["B", "Splits text into units such as words"], ["C", "Detects image edges"], ["D", "Calculates cosine similarity"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 2, "question": "<p>Why lowercase text?</p>", "options": [["A", "So <code>\"Machine\"</code> and <code>\"machine\"</code> can be treated consistently"], ["B", "To remove every noun"], ["C", "To scale numbers"], ["D", "To create timestamps"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 3, "question": "<p>Which is a stopword-like term?</p>", "options": [["A", "compressor_failure"], ["B", "bearing"], ["C", "the"], ["D", "turbine"]], "answers": ["C"], "multiple": false, "explanation": ""}, {"module": 4, "number": 4, "question": "<p>Stemming and lemmatization both broadly attempt to:</p>", "options": [["A", "Transform related word forms toward a common form"], ["B", "Turn words into timestamps"], ["C", "Detect outliers"], ["D", "Create image pixels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 5, "question": "<p>Bag of Words primarily represents text using:</p>", "options": [["A", "RGB values"], ["B", "Word occurrence counts"], ["C", "Time differences"], ["D", "Category hashing only"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 6, "question": "<p>Which vector matches?</p>", "options": [["A", "<code>[1,1,0,0]</code>"], ["B", "<code>[0,0,1,1]</code>"], ["C", "<code>[0,1,0,1]</code>"], ["D", "<code>[1,0,1,0]</code>"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture defines BoW as a term-frequency vector over the corpus vocabulary.</p>"}, {"module": 4, "number": 7, "question": "<p>What is a major limitation of Bag of Words?</p>", "options": [["A", "It cannot represent numbers"], ["B", "It ignores word positions, syntax and semantic meaning"], ["C", "It requires image data"], ["D", "It cannot count repeated words"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 8, "question": "<p>Given:</p>\n<pre><code class=\"language-text\">machine learning model\n</code></pre>\n<p>Which are the bigrams?</p>", "options": [["A", "<code>machine</code>, <code>learning</code>, <code>model</code>"], ["B", "<code>machine learning</code>, <code>learning model</code>"], ["C", "<code>machine learning model</code> only"], ["D", "<code>machine model</code>"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 9, "question": "<p>Why can bigrams help with:</p>\n<pre><code class=\"language-text\">not good\n</code></pre>", "options": [["A", "They can preserve the phrase as a joint feature"], ["B", "They remove the word <code>not</code>"], ["C", "They convert text into images"], ["D", "They make every word identical"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 10, "question": "<p>The intuition:</p>\n<div class=\"math-display\">$$\\text{TF} =\n\\text{importance/frequency within this document}$$</div>\n<div class=\"math-display\">$$\\text{IDF} =\n\\text{rarity across all documents}$$</div>\n<p>The lecture's core idea is:</p>\n<blockquote>\n<p>common-everywhere terms get penalized; distinctive terms get greater weight.</p>\n</blockquote>\n<p>A word appears in every document.</p>\n<p>Its IDF should generally be:</p>", "options": [["A", "High"], ["B", "Low"], ["C", "Infinite"], ["D", "Random"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 11, "question": "<p>A rare term appears in only a few documents.</p>\n<p>Its IDF tends to be:</p>", "options": [["A", "Higher"], ["B", "Zero"], ["C", "Always negative"], ["D", "Equal to term frequency"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 12, "question": "<p>The lecture gives:</p>\n<div class=\"math-display\">$$\\text{TFIDF}=\\text{TF}\\times \\text{IDF}$$</div>\n<p>True or False?</p>", "options": [["A", "True"], ["B", "False"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 13, "question": "<p>The lecture gives:</p>\n<div class=\"math-display\">$$\\cos(\\theta)\n=\n\\frac{A\\cdot B}\n{\\|A\\|\\|B\\|}$$</div>\n<p>If cosine similarity is close to:</p>\n<div class=\"math-display\">$$1$$</div>\n<p>the documents are:</p>", "options": [["A", "Usually very similar in vector direction"], ["B", "Completely unrelated"], ["C", "Duplicates by definition"], ["D", "Missing data"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 14, "question": "<p>If cosine similarity is near:</p>\n<div class=\"math-display\">$$0$$</div>\n<p>the documents are:</p>", "options": [["A", "Highly aligned"], ["B", "Relatively dissimilar"], ["C", "Always identical"], ["D", "Ordinal"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 15, "question": "<p>A set of unlabeled documents is converted to TF-IDF vectors and automatically grouped into similar topics.</p>\n<p>This is:</p>", "options": [["A", "Regression"], ["B", "Unsupervised clustering"], ["C", "Supervised classification"], ["D", "Reinforcement learning"]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture demonstrates weather documents clustering separately from animal documents.</p>"}, {"module": 4, "number": 16, "question": "<p>What does LDA attempt to discover?</p>", "options": [["A", "Missing values"], ["B", "Latent topics/themes in documents"], ["C", "RGB channels"], ["D", "Numeric outliers"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 17, "question": "<p>In topic modelling, a document may contain:</p>", "options": [["A", "Exactly one word"], ["B", "A mixture of multiple topics"], ["C", "Only one mandatory topic"], ["D", "No numeric representation"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 18, "question": "<p>Which best describes word embeddings?</p>", "options": [["A", "Sparse one-hot vectors only"], ["B", "Dense numerical vectors where semantically related words can be nearby"], ["C", "Timestamps for words"], ["D", "Image pixels"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 19, "question": "<p>Why might vectors for <code>\"king\"</code> and <code>\"queen\"</code> be closer than <code>\"king\"</code> and <code>\"car\"</code>?</p>", "options": [["A", "They occur in more similar linguistic contexts"], ["B", "They have the same spelling"], ["C", "They always have the same length"], ["D", "They are one-hot encoded"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 20, "question": "<p>CBOW roughly predicts:</p>", "options": [["A", "Context from target word"], ["B", "Target word from context"], ["C", "RGB from grayscale"], ["D", "Topic from timestamp"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 21, "question": "<p>Skip-gram roughly predicts:</p>", "options": [["A", "Context from target word"], ["B", "Target word from context"], ["C", "Income from age"], ["D", "Categories from quantiles"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture explicitly contrasts CBOW and Skip-gram this way.</p>"}, {"module": 4, "number": 22, "question": "<p>Suppose:</p>\n<pre><code class=\"language-text\">2026-09-23 14:35:22\n</code></pre>\n<p>You can derive:</p>\n<pre><code class=\"language-text\">year\nmonth\nday\nquarter\nday_of_week\nhour\n</code></pre>\n<p>The lecture explicitly lists these kinds of features.</p>\n<p>Extracting <code>month</code> from a timestamp is:</p>", "options": [["A", "Feature engineering"], ["B", "Data deletion"], ["C", "Topic modelling"], ["D", "Image segmentation"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 23, "question": "<p>Why can extracted time components be better than the raw timestamp?</p>", "options": [["A", "They can expose patterns such as weekend, season or time-of-day"], ["B", "Models cannot process any numeric values"], ["C", "They always reduce rows"], ["D", "They remove categories"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 24, "question": "<p>Suppose:</p>\n<pre><code class=\"language-text\">14:35\n</code></pre>\n<p>becomes:</p>\n<pre><code class=\"language-text\">Afternoon\n</code></pre>\n<p>This combines:</p>", "options": [["A", "Time extraction + binning"], ["B", "TF-IDF + hashing"], ["C", "CNN + clustering"], ["D", "Dummy coding + stemming"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 25, "question": "<p>Malaysia:</p>\n<pre><code class=\"language-text\">14:00 UTC+8\n</code></pre>\n<p>London:</p>\n<pre><code class=\"language-text\">06:00 UTC+0\n</code></pre>\n<p>These may represent:</p>", "options": [["A", "Completely different days only"], ["B", "The same moment in time"], ["C", "Missing data"], ["D", "Image coordinates"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 26, "question": "<p>Why normalize timestamps to UTC?</p>", "options": [["A", "To make global timestamps share a consistent temporal reference"], ["B", "To perform one-hot encoding"], ["C", "To eliminate all seasons"], ["D", "To create TF-IDF vectors"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 27, "question": "<p>Unix Epoch time represents:</p>", "options": [["A", "Days since year 1"], ["B", "Seconds since 1 January 1970 UTC"], ["C", "Months since 1900"], ["D", "Hours since model training"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 28, "question": "<p>Why can epoch/ordinal representations be useful?</p>", "options": [["A", "Easier elapsed-time calculations"], ["B", "They automatically classify observations"], ["C", "They remove images"], ["D", "They eliminate the need for timestamps"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 29, "question": "<p>An RGB image generally has shape:</p>\n<div class=\"math-display\">$$(m,n,c)$$</div>\n<p>where $c$ usually equals:</p>", "options": [["A", "1"], ["B", "2"], ["C", "3"], ["D", "255"]], "answers": ["C"], "multiple": false, "explanation": "<p>Red, Green and Blue channels.</p>"}, {"module": 4, "number": 30, "question": "<p>In:</p>\n<div class=\"math-display\">$$(m,n,3)$$</div>\n<p>$m$ and $n$ represent:</p>", "options": [["A", "Model and noise"], ["B", "Image rows/height and columns/width"], ["C", "Month and number"], ["D", "Mean and normalization"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 31, "question": "<p>The lecture gives approximately:</p>\n<div class=\"math-display\">$$Y=\n0.2125R+\n0.7154G+\n0.0721B$$</div>\n<p>Converting RGB to grayscale changes approximately:</p>\n<div class=\"math-display\">$$(m,n,3)$$</div>\n<p>to:</p>", "options": [["A", "<div class=\"math-display\">$$(m,n)$$</div>"], ["B", "<div class=\"math-display\">$$(3,m,n,3)$$</div>"], ["C", "<div class=\"math-display\">$$1$$</div>"], ["D", "<div class=\"math-display\">$$(m^2,n^2)$$</div>"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 32, "question": "<p>Why might grayscale be useful?</p>", "options": [["A", "Reduces dimensionality while preserving intensity information"], ["B", "Adds more colour channels"], ["C", "Converts images into text"], ["D", "Creates categories automatically"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 33, "question": "<p>A matrix:</p>\n<pre><code class=\"language-text\">0.2 0.5\n0.7 0.9\n</code></pre>\n<p>can become:</p>\n<pre><code class=\"language-text\">[0.2, 0.5, 0.7, 0.9]\n</code></pre>\n<p>This is called:</p>", "options": [["A", "Flattening"], ["B", "Tokenization"], ["C", "Binning"], ["D", "Lemmatization"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 34, "question": "<p>What is the main drawback?</p>", "options": [["A", "Spatial neighbour relationships are largely lost"], ["B", "Pixel values disappear"], ["C", "Image size doubles"], ["D", "It creates extra colour channels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 35, "question": "<p>An image histogram can represent:</p>", "options": [["A", "Number of pixels falling into different intensity ranges"], ["B", "Word frequencies"], ["C", "Time zones"], ["D", "Categorical rankings"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 36, "question": "<p>A mostly bright image is likely to have more pixel counts:</p>", "options": [["A", "At higher intensity values"], ["B", "Only at zero"], ["C", "At negative intensity"], ["D", "At random text labels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 37, "question": "<p>Which can summarize image intensity distributions?</p>", "options": [["A", "Mean, variance, skewness, kurtosis"], ["B", "Only SQL queries"], ["C", "TF-IDF only"], ["D", "Generation labels"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 38, "question": "<p>What does edge detection primarily seek?</p>", "options": [["A", "Sharp changes in intensity/brightness"], ["B", "Missing image labels"], ["C", "Word counts"], ["D", "Time zones"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 39, "question": "<p>Which algorithm is specifically mentioned in the lecture?</p>", "options": [["A", "Canny"], ["B", "Apriori"], ["C", "PageRank"], ["D", "ARIMA"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 40, "question": "<p>HOG stands for:</p>", "options": [["A", "Histogram of Oriented Gradients"], ["B", "Hierarchy of Global Groups"], ["C", "High Order Gaussian"], ["D", "Hash of Gradients"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 41, "question": "<p>HOG primarily captures:</p>", "options": [["A", "Edge directions/orientations and local shape information"], ["B", "Word semantics"], ["C", "SQL structure"], ["D", "Datetime offsets"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 42, "question": "<p>SURF is mainly associated with:</p>", "options": [["A", "Localized feature extraction around interesting image points"], ["B", "Text stemming"], ["C", "Time binning"], ["D", "Categorical encoding"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 43, "question": "<p>SURF stands for:</p>", "options": [["A", "Standard Unified Regression Features"], ["B", "Speeded Up Robust Features"], ["C", "Structured Universal Ranking Formula"], ["D", "Scaled Unsupervised Random Forest"]], "answers": ["B"], "multiple": false, "explanation": ""}, {"module": 4, "number": 44, "question": "<p>Visual Bag of Words is inspired by:</p>", "options": [["A", "Text Bag of Words"], ["B", "Min-Max scaling"], ["C", "Regression"], ["D", "Epoch timestamps"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 45, "question": "<p>The basic VBOW flow is approximately:</p>\n<div class=\"math-flow\" role=\"img\" aria-label=\"Image → Local descriptors → Clusters → Visual words → Count vector\"><span>Image</span><i aria-hidden=\"true\">→</i><span>Local descriptors</span><i aria-hidden=\"true\">→</i><span>Clusters</span><i aria-hidden=\"true\">→</i><span>Visual words</span><i aria-hidden=\"true\">→</i><span>Count vector</span></div>\n<p>True or False?</p>", "options": [["A", "True"], ["B", "False"]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture describes clustering local descriptors and treating clusters as visual words.</p>"}, {"module": 4, "number": 46, "question": "<p>What major change do CNNs bring compared with traditional image-feature engineering?</p>", "options": [["A", "CNNs can learn useful feature representations automatically"], ["B", "CNNs require all features to be manually designed"], ["C", "CNNs convert images to SQL"], ["D", "CNNs eliminate numerical input"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 47, "question": "<p>Early CNN layers commonly learn:</p>", "options": [["A", "Edges and lines"], ["B", "Entire high-level objects immediately"], ["C", "Time zones"], ["D", "Document topics"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 48, "question": "<p>Deeper CNN layers generally learn:</p>", "options": [["A", "Increasingly complex patterns/concepts"], ["B", "Only pixel brightness"], ["C", "Missing-value indicators"], ["D", "Stopwords"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 49, "question": "<p>The lecture closes with the correct order:</p>\n<div class=\"math-flow\" role=\"img\" aria-label=\"Train/Test Split → Fit Transformers on Train → Transform Train → Transform Test → Train Model → Evaluate\"><span>Train/Test Split</span><i aria-hidden=\"true\">→</i><span>Fit Transformers on Train</span><i aria-hidden=\"true\">→</i><span>Transform Train</span><i aria-hidden=\"true\">→</i><span>Transform Test</span><i aria-hidden=\"true\">→</i><span>Train Model</span><i aria-hidden=\"true\">→</i><span>Evaluate</span></div>\n<p>Why split train/test <strong>before</strong> fitting TF-IDF, quantile binning, scalers or encoders?</p>", "options": [["A", "To avoid test information leaking into preprocessing"], ["B", "To increase image resolution"], ["C", "To convert categories to text"], ["D", "To reduce rows automatically"]], "answers": ["A"], "multiple": false, "explanation": ""}, {"module": 4, "number": 50, "question": "<p>Which is wrong?</p>", "options": [["A", "Fit TF-IDF vocabulary on train, transform train/test"], ["B", "Fit encoder on train, reuse on test"], ["C", "Refit preprocessing separately on test"], ["D", "Split before learning preprocessing parameters"]], "answers": ["C"], "multiple": false, "explanation": ""}];
window.DIFFICULT_BANK = [{"module": 1, "number": "D1", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>Which completion of Tom Mitchell's definition is exactly right? \"A program learns from experience E with respect to task T and performance measure P if...\"</p>", "options": [["A", "...its experience E grows each time it is evaluated with P on T."], ["B", "...its performance at tasks in T, as measured by P, improves with experience E."], ["C", "...it maximises P on the data in E, whatever the task."], ["D", "...the task T becomes easier as more experience E is stored."]], "answers": ["B"], "multiple": false, "explanation": "<p>Learning is defined by <strong>improvement of P on T caused by E</strong>. A only says data accumulates (storing data is not learning). C confuses fitting the training data with learning a task — maximising P on E alone is exactly what an overfitted model does. D says the task changes; in Mitchell's definition the task is fixed and the <em>system</em> gets better at it.</p>"}, {"module": 1, "number": "D2", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>The lecture classifies ML along three independent questions. Which pairing of answers to question is <strong>wrong</strong>?</p>", "options": [["A", "Supervised / Unsupervised / Reinforcement — does the machine receive correct answers while learning?"], ["B", "Batch / Online — how does new data arrive, i.e. when does the model learn?"], ["C", "Batch / Online — does the model generalise by comparing stored examples?"], ["D", "Instance-based / Model-based — how does it generalise to new cases?"]], "answers": ["C"], "multiple": false, "explanation": "<p>\"Comparing stored examples\" is the <strong>instance-based vs model-based</strong> dimension, not batch vs online. A, B and D are the lecture's three correct pairings. The trap is that both C and D talk about generalisation — but only D's options (instance vs model) answer it.</p>"}, {"module": 1, "number": "D3", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>What does SEMMA stand for, in order?</p>", "options": [["A", "Select, Explore, Modify, Model, Assess"], ["B", "Sample, Evaluate, Modify, Model, Assess"], ["C", "Sample, Explore, Modify, Model, Assess"], ["D", "Sample, Explore, Manipulate, Model, Apply"]], "answers": ["C"], "multiple": false, "explanation": "<p><strong>Sample, Explore, Modify, Model, Assess.</strong> A swaps in KDD's \"Selection\"; B swaps in CRISP-DM's \"Evaluation\"; D changes two words. Each distractor borrows a real step name from a neighbouring framework, which is exactly how exam distractors are built.</p>"}, {"module": 1, "number": "D4", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>A spam filter classifies every incoming email within milliseconds, but its parameters only change when the team retrains it every Sunday. Why is it <strong>not</strong> online learning?</p>", "options": [["A", "Because online learning means the model is hosted on the internet, and this one runs on a local server."], ["B", "Because \"online\" describes how the model learns — incremental parameter updates as data arrives — not how fast it predicts."], ["C", "Because spam filtering is a classification task, and online learning only applies to regression."], ["D", "Because weekly retraining is too frequent to count as batch learning, so it is a third category."]], "answers": ["B"], "multiple": false, "explanation": "<p>Batch vs online is about <strong>when learning happens</strong>. Fast real-time <em>prediction</em> says nothing about learning; this model learns in weekly batch events, so it is batch learning. A is the classic \"online = internet\" confusion. C is false — online learning works for any supervised task. D invents a category; periodic retraining is the textbook batch pattern.</p>"}, {"module": 1, "number": "D5", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>As you increase a model's complexity, its training error keeps falling. What does that fact <strong>on its own</strong> tell you about generalisation?</p>", "options": [["A", "Nothing — training error falls with flexibility even after test error has started to rise, so you need unseen data to judge generalisation."], ["B", "The model is generalising better, because lower training error always means lower test error."], ["C", "The model is overfitting, because falling training error is the definition of overfitting."], ["D", "The model is underfitting, because it has not yet reached zero training error."]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture's complexity graph shows training error decreasing monotonically while <strong>test error is U-shaped</strong>. So falling training error is compatible with both improving and worsening generalisation. B ignores the right half of the U. C is wrong — overfitting is a <em>gap</em> between training and test performance, not falling training error. D wrongly treats zero training error as the goal.</p>"}, {"module": 1, "number": "D6", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>A hospital trains on 2 million records — all from one specialist cardiac clinic — and plans to deploy nationwide. Why would collecting another 2 million records <strong>from the same clinic</strong> not fix the main problem?</p>", "options": [["A", "Because doubling the data always causes underfitting."], ["B", "Because the extra data would make the model overfit to cardiac patients."], ["C", "Because large datasets require online learning, which this hospital does not use."], ["D", "Because the problem is nonrepresentative data: more of the same population adds no information about the patients the model will actually see."]], "answers": ["D"], "multiple": false, "explanation": "<p>The lecture separates <strong>quantity</strong> from <strong>representativeness</strong>. The model will generalise to a population it has never sampled; more cardiac-clinic data cannot represent rural GPs or children. A and C are false generalisations. B is tempting, but the issue is not memorising noise — it is that the training distribution differs from the deployment distribution.</p>"}, {"module": 1, "number": "X11", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": "Master's", "question": "<p>A language model is pre-trained by predicting masked words in billions of unlabelled sentences, then fine-tuned on 1,000 labelled reviews for sentiment. How is this best classified?</p>", "options": [["A", "Reinforcement learning, because the model is rewarded for correct words."], ["B", "Self-supervised pre-training (labels created from the data itself) followed by supervised fine-tuning."], ["C", "Unsupervised clustering followed by classification."], ["D", "Semi-supervised learning in the sense the lecture slide uses for reinforcement learning."]], "answers": ["B"], "multiple": false, "explanation": "<p>Masking creates labels from the raw text itself (<strong>self-supervised</strong>); the 1,000 labelled reviews make the second stage <strong>supervised</strong>. A: there is no environment or delayed reward. C: no clusters are formed. D: the lecture's slide calls RL \"semi-supervised\", but standard terminology separates RL from semi-supervised learning — and neither describes masked-word pre-training.</p>"}, {"module": 1, "number": "D7", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>A k-NN classifier predicts whether a student passes. The four nearest stored students to a new student are:</p>\n<table>\n<thead>\n<tr>\n<th>Distance</th>\n<th>Label</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1.0</td>\n<td>Fail</td>\n</tr>\n<tr>\n<td>1.2</td>\n<td>Pass</td>\n</tr>\n<tr>\n<td>1.3</td>\n<td>Pass</td>\n</tr>\n<tr>\n<td>3.0</td>\n<td>Fail</td>\n</tr>\n</tbody>\n</table>\n<p>What does it predict with <strong>k = 1</strong> and with <strong>k = 3</strong> (simple majority vote)?</p>", "options": [["A", "Fail with k = 1, Pass with k = 3"], ["B", "Pass with k = 1, Pass with k = 3"], ["C", "Fail with k = 1, Fail with k = 3"], ["D", "Pass with k = 1, Fail with k = 3"]], "answers": ["A"], "multiple": false, "explanation": "<p>k = 1 uses only the closest example (distance 1.0, <strong>Fail</strong>). k = 3 uses the three closest — Fail, Pass, Pass — and the majority is <strong>Pass</strong>. The flip shows why k matters: a small k follows individual (possibly noisy) neighbours, a larger k smooths the decision. The fourth neighbour (3.0) is never used in either case.</p>"}, {"module": 1, "number": "D8", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>A bank has 1,000,000 transactions, of which 0.2% are fraudulent. A model labels <strong>every</strong> transaction as legitimate. What are its accuracy and the number of frauds it catches?</p>", "options": [["A", "0.2% accuracy, 2,000 frauds caught"], ["B", "99.8% accuracy, 0 frauds caught"], ["C", "99.8% accuracy, 2,000 frauds caught"], ["D", "50% accuracy, 1,000 frauds caught"]], "answers": ["B"], "multiple": false, "explanation": "<p>0.2% of 1,000,000 = 2,000 frauds. Predicting \"legitimate\" for everything is right for the 998,000 legitimate ones → <strong>99.8% accuracy</strong>, and catches <strong>0</strong> frauds. This is why the lecture insists evaluation must connect back to the business objective: accuracy alone rewards a useless model on imbalanced data.</p>"}, {"module": 1, "number": "D9", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>A model-based learner fitted $\\text{Price} = 250 \\times \\text{Size} + 50{,}000$ on houses between 800 and 2,500 sq ft. A client asks for a 20,000 sq ft estate. What does the model output, and what is the main concern?</p>", "options": [["A", "RM550,000 — the model caps predictions at its training range."], ["B", "RM5,050,000, and it is reliable because model-based learners generalise to any input."], ["C", "RM5,050,000, but this is extrapolation far beyond the training range, so the learned relationship may not hold."], ["D", "An instance-based learner would return exactly RM5,050,000 as well, so there is no concern."]], "answers": ["C"], "multiple": false, "explanation": "<p>250 × 20,000 + 50,000 = <strong>5,050,000</strong>. A linear model will happily extrapolate, but nothing in the data shows the relationship stays linear at 8× the largest training house — that is a <strong>representativeness</strong> problem in the input space. A invents a cap. B overstates what \"generalisation\" means. D is false: a k-NN model would return values near its largest stored houses, not an extrapolated number.</p>"}, {"module": 1, "number": "X1", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Master's", "question": "<p>For squared error, expected test error decomposes as $\\text{Bias}^2 + \\text{Variance} + \\text{Irreducible noise}$. A model has bias 0.3, variance 0.04 and noise variance 0.01. What is its expected squared error?</p>", "options": [["A", "0.35"], ["B", "0.05"], ["C", "0.10"], ["D", "0.14"]], "answers": ["D"], "multiple": false, "explanation": "<p>$0.3^2 + 0.04 + 0.01 = 0.09 + 0.04 + 0.01 = 0.14$. A adds the bias without squaring it. B drops the bias entirely. C forgets the noise term. Underfitting in the lecture's sense is <strong>high bias</strong>; overfitting is <strong>high variance</strong> — this decomposition is the formal version of the complexity curve.</p>"}, {"module": 1, "number": "X3", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Master's", "question": "<p>What is the largest number of points in general position in 2D that a linear classifier (a line with a bias term) can <strong>shatter</strong> — i.e. separate correctly under every possible labelling?</p>", "options": [["A", "2"], ["B", "3"], ["C", "4"], ["D", "Unlimited"]], "answers": ["B"], "multiple": false, "explanation": "<p>The VC dimension of linear classifiers in $\\mathbb{R}^d$ is $d+1$, so in 2D it is <strong>3</strong>. Any 3 non-collinear points can be split in all $2^3$ ways. For 4 points, the XOR labelling (opposite corners share a label) cannot be separated by any line. This is the formal measure of the \"model capacity\" that drives the overfitting/underfitting trade-off.</p>"}, {"module": 1, "number": "X5", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Industry", "question": "<p>Of 10,000 transactions, 100 are fraud. A model flags 200 transactions; 80 of them are truly fraud. What are its precision and recall?</p>", "options": [["A", "Precision 0.40, recall 0.80"], ["B", "Precision 0.80, recall 0.40"], ["C", "Precision 0.80, recall 0.80"], ["D", "Precision 0.40, recall 0.008"]], "answers": ["A"], "multiple": false, "explanation": "<p>Precision = true flagged / all flagged = 80 / 200 = <strong>0.40</strong>. Recall = true flagged / all frauds = 80 / 100 = <strong>0.80</strong>. B swaps the two. D divides by all 10,000 transactions. Precision and recall are how a fraud team turns \"don't trust 99.9% accuracy\" into numbers that match the business cost of missed frauds vs blocked customers.</p>"}, {"module": 1, "number": "X7", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Master's", "question": "<p>Data are uniform in a $d$-dimensional unit cube. To capture 10% of the data, a cube-shaped neighbourhood needs edge length $0.1^{1/d}$. In $d = 10$ that is about:</p>", "options": [["A", "0.10"], ["B", "0.32"], ["C", "0.79"], ["D", "0.98"]], "answers": ["C"], "multiple": false, "explanation": "<p>$0.1^{1/10} \\approx 0.794$. The neighbourhood must span <strong>79%</strong> of each axis to hold 10% of the points. So \"nearest\" neighbours are no longer local, which undermines instance-based methods like k-NN — the <strong>curse of dimensionality</strong>. B is the 2D answer ($\\sqrt{0.1}$). D is roughly the $d = 100$ answer.</p>"}, {"module": 1, "number": "D10", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>Three models are evaluated on the same split:</p>\n<table>\n<thead>\n<tr>\n<th>Model</th>\n<th style=\"text-align: right;\">Train accuracy</th>\n<th style=\"text-align: right;\">Test accuracy</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>A</td>\n<td style=\"text-align: right;\">72%</td>\n<td style=\"text-align: right;\">70%</td>\n</tr>\n<tr>\n<td>B</td>\n<td style=\"text-align: right;\">99%</td>\n<td style=\"text-align: right;\">71%</td>\n</tr>\n<tr>\n<td>C</td>\n<td style=\"text-align: right;\">88%</td>\n<td style=\"text-align: right;\">86%</td>\n</tr>\n</tbody>\n</table>\n<p>Which reading is most accurate?</p>", "options": [["A", "B is best because it has the highest training accuracy."], ["B", "A overfits, B underfits, C is in between."], ["C", "All three generalise equally, because their test accuracies are within 16 points."], ["D", "A underfits, B overfits, and C generalises best."]], "answers": ["D"], "multiple": false, "explanation": "<p>A is poor on <strong>both</strong> sets (too simple → underfitting). B has a 28-point <strong>gap</strong> between train and test (memorising → overfitting). C is high on both with a small gap — the sweet spot. A is the \"lowest training error wins\" trap the lecture warns about; B reverses the definitions; C ignores both the levels and the gaps.</p>"}, {"module": 1, "number": "D11", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>A recommendation model was trained once on January data. Without any code changes, its accuracy falls a little every month until June. What is the most likely explanation, and which ML dimension does it point to?</p>", "options": [["A", "The data the model sees has drifted away from January's; a batch model never updates, so it needs periodic retraining or online learning."], ["B", "The model is overfitting more every month, so it needs fewer features."], ["C", "More data arrived each month, which made the model underfit."], ["D", "The model is instance-based and its stored examples are being deleted."]], "answers": ["A"], "multiple": false, "explanation": "<p>The model is unchanged; the <strong>world</strong> changed — that is drift. The lecture's batch-vs-online dimension exists for exactly this: batch models stay frozen until retrained, while online learners can adapt. B: the model's complexity hasn't changed, so its overfitting can't grow. C: the model never sees the new data, so it can't affect fitting. D is invented.</p>"}, {"module": 1, "number": "D12", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>A retailer runs k-means to find customer groups. Managers name the clusters \"Budget\", \"Regular\" and \"Premium\", then train a classifier on those names to tag new customers. Which description is correct?</p>", "options": [["A", "The whole pipeline is supervised, because names were added."], ["B", "The whole pipeline is unsupervised, because the labels came from clustering."], ["C", "Stage 1 is unsupervised; stage 2 is supervised learning on labels that stage 1 produced."], ["D", "Stage 2 is reinforcement learning, because managers give feedback."]], "answers": ["C"], "multiple": false, "explanation": "<p>Naming clusters afterwards <strong>does not</strong> make the clustering supervised (the lecture's explicit trap), so A is wrong for stage 1. But once those names are used as targets $y$, stage 2 <em>is</em> supervised — so B is wrong for stage 2. D confuses one-off labelling with a reward signal from an environment.</p>"}, {"module": 1, "number": "X4", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Industry", "question": "<p>A deployed fraud model's <strong>input</strong> distributions are stable (population-stability index ≈ 0 on every feature). Yet as delayed labels arrive, its precision falls from 0.60 to 0.35. What is the most likely diagnosis?</p>", "options": [["A", "Covariate shift — the features have drifted."], ["B", "Concept drift — the relationship $P(y \\mid x)$ has changed (fraudsters changed tactics), so the model must be retrained on recent labelled data."], ["C", "Underfitting — the model was too simple from the start."], ["D", "A data-quality bug, because performance cannot change while inputs are stable."]], "answers": ["B"], "multiple": false, "explanation": "<p>If $P(x)$ is unchanged but performance degrades, the mapping from $x$ to $y$ has changed: <strong>concept drift</strong>. Fraud is the lecture's own example of a changing environment, so online learning or frequent retraining is needed. A is ruled out by the stable PSI. C cannot explain a <em>decline</em> over time. D is false: performance changes whenever $P(y \\mid x)$ changes.</p>"}, {"module": 1, "number": "X6", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Hackathon", "question": "<p>In a sales-forecasting hackathon, your random 5-fold cross-validation score is 0.95, but the private leaderboard (which uses future months) gives 0.70. What is the most likely cause?</p>", "options": [["A", "The model underfits; add more trees."], ["B", "The leaderboard is wrong, because cross-validation is always reliable."], ["C", "Random folds mix future rows into training, so the validation is easier than forecasting the real future; use time-ordered splits."], ["D", "Too few folds; using 10 folds would close the gap."]], "answers": ["C"], "multiple": false, "explanation": "<p>With time-dependent data, random folds let the model learn from rows that come <em>after</em> the rows it is validated on. That leaks future information — the same principle as the lecture's leakage warning, applied to the <strong>split</strong>. Time-based splits (train on the past, validate on the future) estimate real deployment. D keeps the same leak. A and B misread the evidence.</p>"}, {"module": 1, "number": "X10", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Coding", "question": "<p>This streaming code fails on the very first batch:</p>\n<pre><code class=\"language-python\">from sklearn.linear_model import SGDClassifier\nclf = SGDClassifier()\nfor X_batch, y_batch in stream:          # first batch contains only class 0\n    clf.partial_fit(X_batch, y_batch)\n</code></pre>\n<p>Why, and what is the fix?</p>", "options": [["A", "<code>partial_fit</code> doesn't exist; use <code>fit</code> in the loop."], ["B", "Online learning needs the whole dataset in memory; load it first."], ["C", "On the first call the model must be told every possible class: <code>clf.partial_fit(X_batch, y_batch, classes=[0, 1])</code>."], ["D", "The batch is too small; batches need at least 1,000 rows."]], "answers": ["C"], "multiple": false, "explanation": "<p>In incremental (online) learning, a batch may not contain every label. scikit-learn therefore requires <code>classes=</code> on the <strong>first</strong> <code>partial_fit</code> call; without it, it raises an error. A loses the online behaviour — each <code>fit</code> would restart from scratch. B contradicts the point of online / out-of-core learning. D is invented.</p>"}, {"module": 1, "number": "D13", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>A team reports 99.9% accuracy for a card-fraud model and asks to deploy. Which response best reflects CRISP-DM's Evaluation phase?</p>", "options": [["A", "Approve deployment — 99.9% is excellent for any model."], ["B", "Go back to Data Preparation, because accuracy above 99% always means leakage."], ["C", "Deploy now and evaluate later from customer complaints."], ["D", "Ask whether it meets the business objective — frauds caught vs legitimate transactions blocked — before deciding."]], "answers": ["D"], "multiple": false, "explanation": "<p>CRISP-DM's Evaluation phase judges the model <strong>against the business success criteria</strong> defined in Business Understanding, not against a generic metric. With fraud at ~0.1%, 99.9% accuracy can come from catching nothing. B overreacts: high accuracy can be legitimate, but it must be <em>checked</em>. A and C skip evaluation entirely.</p>"}, {"module": 1, "number": "D14", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>A phone app must predict on-device in under 10 ms. The training set has 50 million examples. Which judgement is best?</p>", "options": [["A", "Instance-based (k-NN), because it needs no training and is therefore fastest."], ["B", "Model-based, because predictions use a compact set of learned parameters instead of searching 50 million stored examples."], ["C", "Either is equally suitable, because both generalise from examples."], ["D", "Instance-based, because it is always more accurate than model-based learning."]], "answers": ["B"], "multiple": false, "explanation": "<p>Instance-based learning moves the work to <strong>prediction time</strong>: it must store and search the examples. On a phone with tight memory and a 10 ms budget, 50M examples is impractical. A model-based learner compresses the data into parameters. A confuses \"no training\" with \"fast prediction\". C ignores the deployment constraint. D is a false absolute.</p>"}, {"module": 1, "number": "D15", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>A research group mines five years of student-portal logs to discover interesting behaviour patterns. There is no business client and nothing will be deployed. Which framework's emphasis fits most naturally?</p>", "options": [["A", "KDD, because its whole purpose is turning raw data into knowledge, ending in interpretation."], ["B", "CRISP-DM, because only CRISP-DM can be used for academic data."], ["C", "SEMMA, because it is the only framework with an exploration step."], ["D", "None — frameworks only apply to commercial projects."]], "answers": ["A"], "multiple": false, "explanation": "<p>KDD's endpoint is <strong>knowledge</strong> after interpretation/evaluation, which matches a discovery-focused study. CRISP-DM <em>could</em> be used, but its distinguishing strengths — business understanding and deployment — are exactly what this project lacks, so B's \"only\" is wrong. C is false: KDD has selection/preprocessing and CRISP-DM has data understanding. D is false.</p>"}, {"module": 1, "number": "X2", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "PhD", "question": "<p>In very over-parameterised models (e.g. large neural networks), test error can rise near the point where parameters ≈ training samples, then <strong>fall again</strong> as the model grows further (\"double descent\"). How does this relate to the lecture's U-shaped complexity curve?</p>", "options": [["A", "It proves overfitting does not exist, so the U-curve should be discarded."], ["B", "The U-curve describes the classical regime; beyond the interpolation threshold, implicit regularisation can make larger models generalise better, so complexity alone doesn't determine overfitting."], ["C", "Double descent only happens with k-NN, so the U-curve still holds for every parametric model."], ["D", "Double descent means training error rises again for very large models."]], "answers": ["B"], "multiple": false, "explanation": "<p>Double descent <strong>extends</strong> the classical picture rather than refuting it. The U-curve holds up to the interpolation threshold. Past it, among the many models that fit the training data perfectly, the optimiser tends to find \"simple\" (low-norm) ones, so test error can fall again. A overclaims. C is false — the effect is best known in linear models and neural networks. D is false — training error stays near zero in the over-parameterised regime.</p>"}, {"module": 1, "number": "X8", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Industry", "question": "<p>Learning curves for a churn model show training and validation accuracy converging at about 0.68 as the training set grows from 5k to 500k rows. What is the best next investment?</p>", "options": [["A", "Collect another 500k rows — more data always helps."], ["B", "Add regularisation to reduce variance."], ["C", "Use a simpler model."], ["D", "Increase model capacity or engineer better features, because the curves show high bias."]], "answers": ["D"], "multiple": false, "explanation": "<p>Converged, <strong>low</strong> curves with no gap mean the model can't represent the pattern (underfitting / high bias). The lecture's remedies are a more powerful model and better features. A and B treat the wrong problem: more data and regularisation fix <em>variance</em> (a gap between the curves), which isn't present. C makes the bias worse.</p>"}, {"module": 1, "number": "X9", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Master's", "question": "<p>A team tunes 200 hyperparameter combinations with 5-fold cross-validation and reports the <strong>best</strong> cross-validation score as the model's expected performance. What is wrong?</p>", "options": [["A", "Nothing — cross-validation scores are unbiased."], ["B", "The reported score is optimistically biased, because the folds were used to choose the hyperparameters; estimate performance with nested cross-validation or an untouched test set."], ["C", "5 folds is too few; with 10 folds the best score would be unbiased."], ["D", "Hyperparameter tuning causes underfitting."]], "answers": ["B"], "multiple": false, "explanation": "<p>Picking the best of 200 configurations on the same folds <strong>fits the validation data</strong> — a selection effect, the evaluation-level version of overfitting. An honest estimate needs data that played no part in any choice: an outer loop (nested CV) or a held-out test set. C keeps the same selection bias. D is unrelated.</p>"}, {"module": 1, "number": "D16", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>Design the learning setup for a news app. Users' interests shift daily, the click history is far too large for memory, and every impression is logged as clicked / not clicked. Which design fits the lecture's concepts best?</p>", "options": [["A", "Unsupervised clustering retrained once a year on a sample."], ["B", "Instance-based k-NN that keeps every click in RAM."], ["C", "Reinforcement learning only, with no use of the logged clicks."], ["D", "Supervised learning (clicks are labels), trained online / out-of-core in mini-batches, with performance monitored over time."]], "answers": ["D"], "multiple": false, "explanation": "<p>Clicks are labels → <strong>supervised</strong>. Interests shift daily → <strong>online</strong> updates. The history doesn't fit in memory → <strong>out-of-core</strong> mini-batches. A ignores both the labels and the drift. B fails on memory. C throws away a large labelled signal that already exists.</p>"}, {"module": 1, "number": "D17", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>You must design an experiment that shows convincingly whether your model overfits. Which plan is best?</p>", "options": [["A", "Compare the training accuracy of several models; the highest is the least overfit."], ["B", "Hold out data the model never trains on, then plot training and held-out error as complexity (or training size) increases, and look for a widening gap."], ["C", "Evaluate the model twice on the training data to check that the score is stable."], ["D", "Add more features until training accuracy reaches 100%."]], "answers": ["B"], "multiple": false, "explanation": "<p>Overfitting is defined as performing well on training data but <strong>not generalising</strong>, so it can only be shown with unseen data. Plotting both curves against complexity reproduces the lecture's key graph and shows where the gap opens. A and C only use training data; D actively <em>causes</em> overfitting.</p>"}, {"module": 1, "number": "D18", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>Your manager says: \"Use ML to reduce churn.\" Which plan best follows CRISP-DM?</p>", "options": [["A", "Define churn and a measurable target (e.g. cut churn by 2 points at an acceptable offer cost) → check what data exists and its quality → prepare features → model → evaluate against the target → deploy with monitoring, looping back where needed."], ["B", "Pick the most accurate algorithm from a benchmark → train on all data → deploy → define what churn means afterwards."], ["C", "Sample → Explore → Modify → Model → Assess, and stop there."], ["D", "Collect as much data as possible first, then decide which business problem it can solve."]], "answers": ["A"], "multiple": false, "explanation": "<p>CRISP-DM <strong>starts</strong> with Business Understanding (what churn is, what success means), then Data Understanding, Preparation, Modeling, Evaluation against the business target, and Deployment — and it is iterative. B inverts the order. C is SEMMA, which has no business-understanding or deployment phase. D lets the data choose the problem.</p>"}, {"module": 1, "number": "X12", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": "Industry", "question": "<p>CRISP-DM ends at Deployment, but a deployed fraud model can quietly decay. Which monitoring design best closes the loop?</p>", "options": [["A", "Re-run the original test set every month; if the score is unchanged, nothing has changed."], ["B", "Monitor input drift and the prediction distribution, track precision/recall as delayed labels arrive, alert when they cross thresholds, and retrain from versioned data/model snapshots, feeding back into Business and Data Understanding."], ["C", "Retrain from scratch every day regardless of performance, with no versioning."], ["D", "Only log errors that customers complain about."]], "answers": ["B"], "multiple": false, "explanation": "<p>Monitoring must catch <strong>covariate drift</strong> (inputs), output shift, and <strong>concept drift</strong> (label-based metrics), and versioning makes retraining reproducible — the operational version of CRISP-DM's loop back to the start. A: a fixed old test set cannot reveal drift. C wastes effort and gives no idea whether a change helped. D only sees failures customers happen to notice.</p>"}, {"module": 2, "number": "D1", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>Which sequence is the correct CRISP-DM phase order?</p>", "options": [["A", "Data Understanding → Business Understanding → Data Preparation → Modeling → Evaluation → Deployment"], ["B", "Business Understanding → Data Preparation → Data Understanding → Modeling → Evaluation → Deployment"], ["C", "Business Understanding → Data Understanding → Data Preparation → Modeling → Evaluation → Deployment"], ["D", "Business Understanding → Data Understanding → Modeling → Data Preparation → Evaluation → Deployment"]], "answers": ["C"], "multiple": false, "explanation": "<p><strong>Business → Data Understanding → Data Preparation → Modeling → Evaluation → Deployment.</strong> Each distractor swaps one adjacent pair. A starts with data before the problem is defined; B prepares data before understanding it; D models before preparing.</p>"}, {"module": 2, "number": "D2", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>Which <strong>single</strong> pandas call shows each column's data type <strong>and</strong> its non-null count?</p>", "options": [["A", "<code>df.info()</code>"], ["B", "<code>df.describe()</code>"], ["C", "<code>df.isna().sum()</code>"], ["D", "<code>df.dtypes</code>"]], "answers": ["A"], "multiple": false, "explanation": "<p><code>info()</code> shows the row count, columns, dtypes and non-null counts together. <code>describe()</code> gives statistics (mean, std, min, max) but no dtypes. <code>isna().sum()</code> gives missing counts only. <code>dtypes</code> gives types only.</p>"}, {"module": 2, "number": "D3", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>How does the lecture define data leakage <strong>in preprocessing</strong>?</p>", "options": [["A", "Losing rows when <code>dropna()</code> is applied."], ["B", "Using information from the test set — such as recalculating scaling parameters on it — which falsely inflates accuracy."], ["C", "Saving the trained model to a public repository."], ["D", "Training on more columns than the model needs."]], "answers": ["B"], "multiple": false, "explanation": "<p>That is the lecture's own definition, from its final assessment slide. A is data loss, not leakage. C is a security issue. D concerns feature selection.</p>"}, {"module": 2, "number": "D4", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>Why must a deployed pipeline <strong>reuse</strong> the min/max learned on training data instead of recomputing them for each incoming customer?</p>", "options": [["A", "Because recomputing is slower."], ["B", "Because the deployment server cannot import scikit-learn."], ["C", "Because a single customer has no min or max, so the result would be 0."], ["D", "Because the model learned on features defined by those parameters; recomputing changes what a value means (RM10,000 would no longer map to ≈ 0.444)."]], "answers": ["D"], "multiple": false, "explanation": "<p>Preprocessing <strong>defines the representation</strong> the model was trained on. If the ruler changes at deployment, identical raw inputs become different features and predictions break silently. A and B are incidental. C is half-true for a single row, but the principle holds for whole batches too: recomputing on new data shifts the meaning of every feature.</p>"}, {"module": 2, "number": "D5", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>For a <strong>linear</strong> model, why is one-hot encoding usually better than label encoding for <code>Country = Malaysia / Japan / Brazil</code>?</p>", "options": [["A", "Label encoding makes the model treat countries as ordered, evenly spaced quantities (Brazil = 2 × Japan), relationships that don't exist."], ["B", "One-hot encoding uses fewer columns."], ["C", "Label encoding cannot be stored in pandas."], ["D", "One-hot encoding sorts the countries alphabetically."]], "answers": ["A"], "multiple": false, "explanation": "<p>A linear model multiplies each feature by a weight, so codes 0/1/2 impose an <strong>order and equal spacing</strong>. One-hot gives each country its own indicator with no implied magnitude. B is backwards — one-hot uses <em>more</em> columns. C and D are false.</p>"}, {"module": 2, "number": "D6", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>Why does feature scaling change k-NN's predictions but <strong>not</strong> the split thresholds chosen by a decision tree?</p>", "options": [["A", "Trees ignore numeric features."], ["B", "k-NN combines features into one distance, so large-unit features dominate; a tree splits on one feature at a time by threshold, and min-max or z-scaling keeps each feature's ordering."], ["C", "Scaling changes the labels for k-NN only."], ["D", "Decision trees always scale data internally."]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture's rule is to ask whether the algorithm is <strong>sensitive to feature magnitude</strong>. Distances mix units (income dwarfs age). A tree compares one feature against a threshold, and monotonic rescaling leaves the order of values — and therefore the same partitions — unchanged. A, C and D are false.</p>"}, {"module": 2, "number": "X3", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": "Master's", "question": "<p><code>income</code> is missing mostly for high earners who refuse to disclose it. Which missing-data mechanism is this?</p>", "options": [["A", "MCAR — missing completely at random."], ["B", "MAR — missing at random given the other observed variables."], ["C", "Not a missing-data problem, because the value is recorded as NaN."], ["D", "MNAR — missing not at random: the probability of missingness depends on the unobserved income itself."]], "answers": ["D"], "multiple": false, "explanation": "<p>The chance of being missing depends on the <strong>value that is missing</strong> (high income → refuses). That is MNAR, the hardest case: no simple imputation is unbiased, which is why the lecture warns that mean filling can introduce bias. MCAR would be random loss. MAR would depend only on observed fields, such as job title.</p>"}, {"module": 2, "number": "D7", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>Min-max scaling was fitted on training incomes from RM2,000 to RM20,000. A new customer earns <strong>RM26,000</strong>. With the training parameters reused, what is the scaled value?</p>", "options": [["A", "1.000"], ["B", "1.333"], ["C", "0.444"], ["D", "0.000"]], "answers": ["B"], "multiple": false, "explanation": "<p>$(26{,}000 - 2{,}000) / (20{,}000 - 2{,}000) = 24{,}000 / 18{,}000 \\approx 1.333$. Values outside the training range map <strong>outside 0–1</strong>, and that is correct and honest. A assumes clipping, which <code>MinMaxScaler</code> doesn't do by default. C is RM10,000's value. D is what you'd get by \"refitting\" on a single row.</p>"}, {"module": 2, "number": "D8", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>A feature has values <code>2, 4, 4, 4, 5, 5, 7, 9</code> (mean 5, population standard deviation 2). What is the z-score of 9?</p>", "options": [["A", "1.0"], ["B", "4.0"], ["C", "2.0"], ["D", "0.5"]], "answers": ["C"], "multiple": false, "explanation": "<p>$z = (9 - 5)/2 = 2.0$: two standard deviations above the mean. B forgets to divide by σ. A and D use the wrong spread. <code>StandardScaler</code> uses this population standard deviation (ddof = 0).</p>"}, {"module": 2, "number": "D9", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>Given:</p>\n<table>\n<thead>\n<tr>\n<th>user_type</th>\n<th style=\"text-align: right;\">price</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>New</td>\n<td style=\"text-align: right;\">100</td>\n</tr>\n<tr>\n<td>New</td>\n<td style=\"text-align: right;\">200</td>\n</tr>\n<tr>\n<td>Premium</td>\n<td style=\"text-align: right;\">500</td>\n</tr>\n<tr>\n<td>Premium</td>\n<td style=\"text-align: right;\">700</td>\n</tr>\n<tr>\n<td>Returning</td>\n<td style=\"text-align: right;\">150</td>\n</tr>\n<tr>\n<td>Returning</td>\n<td style=\"text-align: right;\">250</td>\n</tr>\n</tbody>\n</table>\n<p>What is the <code>mean</code> value for <strong>Returning</strong> in <code>df.groupby(\"user_type\")[\"price\"].agg([\"mean\", \"max\"])</code>?</p>", "options": [["A", "250"], ["B", "150"], ["C", "400"], ["D", "200"]], "answers": ["D"], "multiple": false, "explanation": "<p>Split → Returning: {150, 250}; apply mean → <strong>200</strong>; combine into one row per group. A is that group's max. B is its min. C is the sum.</p>"}, {"module": 2, "number": "X5", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Industry", "question": "<p><code>RobustScaler</code> computes $(x - \\text{median}) / \\text{IQR}$. For the values <code>10, 12, 13, 15, 1000</code> (median 13, Q1 = 12, Q3 = 15), what is the scaled value of 15?</p>", "options": [["A", "0.667"], ["B", "0.002"], ["C", "1.000"], ["D", "329.0"]], "answers": ["A"], "multiple": false, "explanation": "<p>$(15 - 13)/(15 - 12) = 2/3 \\approx 0.667$. D is the outlier 1000's value: it stays extreme, but it no longer squashes everyone else. B mimics min-max, where 1000 stretches the range and every normal value collapses near 0. That's why robust scaling is preferred for outlier-heavy features, building on the lecture's mean-vs-median logic.</p>"}, {"module": 2, "number": "X6", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Coding", "question": "<p>Using the same six-row table as the <code>groupby</code> question (Premium prices 500 and 700), what is <code>dev</code> for the Premium row with price <strong>700</strong>?</p>\n<pre><code class=\"language-python\">df[&quot;dev&quot;] = df[&quot;price&quot;] - df.groupby(&quot;user_type&quot;)[&quot;price&quot;].transform(&quot;mean&quot;)\n</code></pre>", "options": [["A", "0"], ["B", "100"], ["C", "NaN"], ["D", "600"]], "answers": ["B"], "multiple": false, "explanation": "<p><code>transform(\"mean\")</code> broadcasts each group's mean back to <strong>every original row</strong> (same length as <code>df</code>). Premium's mean is 600, so 700 − 600 = <strong>100</strong>. <code>agg</code> would return one row per group and couldn't be subtracted row-wise; that's the agg-vs-transform distinction. D is the group mean itself.</p>"}, {"module": 2, "number": "D10", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p><code>price</code> has 3% missing values, the rows are independent purchases (not a time series), and the distribution has a few extreme prices. Which strategy fits best?</p>", "options": [["A", "Forward fill."], ["B", "Median imputation."], ["C", "Mean imputation."], ["D", "Drop every column that contains a missing value."]], "answers": ["B"], "multiple": false, "explanation": "<p>Independent rows → no meaningful \"previous\" value, so A is unjustified. Extreme values pull the mean, so C is distorted. Dropping the whole <code>price</code> column (D) throws away a key feature to fix 3% of its cells. The <strong>median</strong> keeps the rows and is robust to outliers — the lecture's exact guidance.</p>"}, {"module": 2, "number": "D11", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>A notebook does this:</p>\n<pre><code class=\"language-python\">X_scaled = MinMaxScaler().fit_transform(X)\nX_train, X_test, y_train, y_test = train_test_split(X_scaled, y)\n</code></pre>\n<p>What is the problem?</p>", "options": [["A", "MinMaxScaler cannot be used before splitting for syntax reasons."], ["B", "The scaler learned min/max from rows that end up in the test set, so test information leaked into preprocessing."], ["C", "Scaling should only be applied to the target y."], ["D", "There is no problem, because min-max scaling doesn't change the order of values."]], "answers": ["B"], "multiple": false, "explanation": "<p>The fit saw <strong>all</strong> rows, so the test set influenced the parameters — the lecture's definition of preprocessing leakage. The fix is to split first, fit on train, then transform both. D is the trap: keeping each column's order doesn't stop the test data from shaping the transform.</p>"}, {"module": 2, "number": "D12", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>Two rows look identical — same customer, item, price and timestamp — except <code>transaction_id</code> is 401 vs 402. <code>df.duplicated().sum()</code> returns <strong>0</strong>. Why, and what should you check?</p>", "options": [["A", "<code>duplicated()</code> is broken on timestamps; convert them to strings."], ["B", "pandas treats the first row as unique, so the count is always 0."], ["C", "<code>duplicated()</code> compares all columns by default, and the IDs differ; check <code>df.duplicated(subset=[...])</code> without the ID, then use domain logic to decide whether it's double-logging or two real purchases."], ["D", "The rows are definitely two real purchases, so no check is needed."]], "answers": ["C"], "multiple": false, "explanation": "<p>By default every column must match, so a unique ID hides near-duplicates. Using <code>subset=</code> finds them. Then the lecture's rule applies: <strong>don't delete automatically</strong> — decide whether these are legitimate repeat events. A and B are false. D skips the reasoning step.</p>"}, {"module": 2, "number": "X1", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Coding", "question": "<p>What is wrong with this evaluation, and what fixes it?</p>\n<pre><code class=\"language-python\">X_scaled = StandardScaler().fit_transform(X)\nscores = cross_val_score(KNeighborsClassifier(), X_scaled, y, cv=5)\n</code></pre>", "options": [["A", "Nothing — cross-validation already separates the folds."], ["B", "Use <code>cv=10</code>; five folds are too few for k-NN."], ["C", "The scaler saw every validation fold before CV began; wrap both steps in <code>make_pipeline(StandardScaler(), KNeighborsClassifier())</code> and cross-validate the pipeline."], ["D", "k-NN must not be scaled."]], "answers": ["C"], "multiple": false, "explanation": "<p>Each CV fold acts as a mini test set, but the scaler's mean and std were computed with those rows included — the lecture's leakage rule applied <strong>inside</strong> cross-validation. A <code>Pipeline</code> re-fits the scaler on each training fold only. A is the common misconception. B keeps the leak. D contradicts the lecture: k-NN is distance-based and needs scaling.</p>"}, {"module": 2, "number": "X2", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Industry", "question": "<p>A churn model reaches 0.99 AUC in validation but fails in production. One feature is <code>days_since_cancellation_request</code>. What happened?</p>", "options": [["A", "Target leakage: the feature only exists <strong>after</strong> a customer has started to churn, so it isn't available at prediction time."], ["B", "Underfitting: the model needs more trees."], ["C", "Covariate shift in production."], ["D", "The validation split was too small."]], "answers": ["A"], "multiple": false, "explanation": "<p>A feature that is only recorded <em>because</em> the outcome is happening encodes the label itself, which makes the model look perfect offline. At decision time (before the cancellation request) the value doesn't exist. It is leakage in the same spirit as the lecture's warning: information the model wouldn't really have. B, C and D don't explain a near-perfect score.</p>"}, {"module": 2, "number": "X7", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "PhD", "question": "<p>Kidney-stone data: Treatment A succeeds in 93% of small-stone cases and 73% of large-stone cases. Treatment B succeeds in 87% (small) and 69% (large). Yet <strong>overall</strong>, A has 78% and B 83%. What explains this?</p>", "options": [["A", "A calculation error, because aggregates must preserve subgroup order."], ["B", "Simpson's paradox: A was given mostly to harder large-stone cases, so stone size confounds the aggregate comparison."], ["C", "Treatment B is better; subgroup results should be ignored."], ["D", "Random noise, which disappears with more data."]], "answers": ["B"], "multiple": false, "explanation": "<p>A is better within <strong>each</strong> subgroup but worse overall, because the groups have very different mixes of easy and hard cases. Summaries (the lecture's <code>groupby</code> step) can reverse a conclusion when a confounder is ignored. Choose the grouping from the causal question being asked, not by default. A is false — aggregation can reverse order. C draws the wrong causal conclusion. D: the effect is structural, so more data won't remove it.</p>"}, {"module": 2, "number": "X8", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Industry", "question": "<p>Offline AUC is 0.90, online AUC is 0.70. Logs show the training pipeline used income in RM, while the production service sends income in thousands of RM. What is this, and what fix prevents it?</p>", "options": [["A", "Concept drift; retrain weekly."], ["B", "Overfitting; add regularisation."], ["C", "Training–serving skew; ship the <em>same</em> fitted preprocessing pipeline with the model so both paths share one transformation."], ["D", "Label noise; relabel the data."]], "answers": ["C"], "multiple": false, "explanation": "<p>The same customer gets different feature values offline and online — the industrial version of the lecture's <strong>preprocessing consistency</strong> rule. The robust fix is a single artefact (model plus fitted transformers) used everywhere. A and B treat statistical problems; this is a pipeline-mismatch bug.</p>"}, {"module": 2, "number": "X9", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Hackathon", "question": "<p>You are forecasting tomorrow's demand from a daily time series. Which preprocessing step leaks <strong>future</strong> information?</p>", "options": [["A", "Forward fill (<code>ffill</code>) of missing days."], ["B", "Lag features such as yesterday's demand."], ["C", "Backward fill (<code>bfill</code>) of missing days."], ["D", "A rolling mean of the previous 7 days, shifted by one day."]], "answers": ["C"], "multiple": false, "explanation": "<p><code>bfill</code> copies the <strong>next</strong> known value backwards, so a past row uses information from its future. In a forecasting set-up, that is leakage. <code>ffill</code> (A), lags (B) and shifted rolling windows (D) only use past values. The lecture links ffill/bfill to ordered data; the extension is checking the <em>direction</em> of the fill.</p>"}, {"module": 2, "number": "D13", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>A manager asks: \"Across our 50 stores, does advertising spend relate to sales, and are there unusual stores?\" Which chart answers this best?</p>", "options": [["A", "A scatter plot of ad spend vs sales, one point per store."], ["B", "A line chart of sales by store ID."], ["C", "A bar chart of the 50 stores' sales."], ["D", "A histogram of sales."]], "answers": ["A"], "multiple": false, "explanation": "<p>A relationship between <strong>two numeric variables</strong> calls for a scatter plot, and outlying stores stand out as points far from the trend. B implies an order (time) that store IDs don't have. C compares one variable across categories. D shows one variable's distribution, so it can't show a relationship.</p>"}, {"module": 2, "number": "D14", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>In a 1,000-row dataset, 450 rows are missing <code>income</code>, and you suspect high earners chose not to report it. Which choice is most defensible?</p>", "options": [["A", "<code>dropna()</code>, because missing data can't be trusted."], ["B", "Fill with the mean, because it preserves the average."], ["C", "Forward fill, because it uses real observed values."], ["D", "Keep the rows, impute with a robust statistic, and record that income was missing, because the missingness itself may carry information."]], "answers": ["D"], "multiple": false, "explanation": "<p>Dropping loses <strong>45%</strong> of the data (A). If high earners hide income, the mean of the <em>observed</em> values underestimates them, so B adds bias. C is meaningless for unordered rows. The lecture frames missing-value handling as a <strong>reasoning problem</strong>: keep the data, use a robust fill, and don't hide the fact that it was missing.</p>"}, {"module": 2, "number": "D15", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>An API returns JSON customers, each with a nested list of orders. You must predict <strong>customer churn</strong>. Which flattening is most defensible?</p>", "options": [["A", "One row per order, repeating the customer's fields on each row."], ["B", "One row per customer, with aggregated order features (order count, total spend, days since last order)."], ["C", "Drop the orders, because nested data can't be used in ML."], ["D", "One row per order, with churn copied to each order row."]], "answers": ["B"], "multiple": false, "explanation": "<p>The prediction unit is the <strong>customer</strong>, so each row should be one customer. A and D multiply each customer by their order count. That over-weights heavy buyers, and the same customer's rows can land in both train and test, a leak. C throws away the most predictive behaviour. Aggregation turns nested data into the rows = observations, columns = features shape.</p>"}, {"module": 2, "number": "X4", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Hackathon", "question": "<p>A medical-imaging hackathon has 20,000 X-rays from 4,000 patients (about 5 images each). Random 5-fold CV gives 0.96, while the hidden test set (new patients) gives 0.81. Which validation is most defensible?</p>", "options": [["A", "Stratified K-fold on the label."], ["B", "More folds with random splitting."], ["C", "<code>GroupKFold</code> with <code>patient_id</code> as the group, so no patient appears in both train and validation."], ["D", "Validate on the training set to avoid wasting data."]], "answers": ["C"], "multiple": false, "explanation": "<p>Images of the same patient are near-duplicates. Random folds put them on both sides, which is the lecture's <strong>duplicate-leakage</strong> trap at scale. Grouping by patient simulates \"new patients\". A and B keep the leak. D measures memorisation.</p>"}, {"module": 2, "number": "X11", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Master's", "question": "<p>Before imputing <code>income</code>, you add a binary column <code>income_missing</code>. When is this most likely to help?</p>", "options": [["A", "Never — it duplicates the imputed value."], ["B", "When missingness is informative (MAR/MNAR, e.g. high earners refusing), because the model can learn from the fact that a value was missing."], ["C", "Only when data is MCAR."], ["D", "Only for k-NN models."]], "answers": ["B"], "multiple": false, "explanation": "<p>If missingness correlates with the target, the indicator carries signal that imputation alone hides. Under MCAR, being missing is pure chance, so the indicator adds little (C is backwards). A ignores that the imputed value and the indicator encode different facts. D is false — tree and linear models use indicators well.</p>"}, {"module": 2, "number": "X12", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Master's", "question": "<p>Two models score 96% and 97% accuracy. Which visualisation would most mislead a decision-maker?</p>", "options": [["A", "A bar chart whose y-axis starts at 0."], ["B", "A bar chart whose y-axis starts at 95%, making one bar look twice as tall as the other."], ["C", "A dot plot with confidence intervals."], ["D", "A table listing both scores and their test-set sizes."]], "answers": ["B"], "multiple": false, "explanation": "<p>Truncating the axis turns a 1-point difference into an apparent 2× difference. The lecture says chart choice must follow the <strong>question</strong>; the extension is that chart <em>design</em> can distort the answer. C and D add uncertainty and context, which is more honest.</p>"}, {"module": 2, "number": "D16", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>Which ordering builds a <strong>deployment-safe</strong> preprocessing workflow?</p>", "options": [["A", "Impute → scale → encode on all data → split → train → evaluate."], ["B", "Split → fit imputer, encoder and scaler on train → transform train and test → train → evaluate → save the fitted preprocessors with the model → apply them unchanged to new data."], ["C", "Split → fit preprocessors separately on train and on test → train → evaluate."], ["D", "Train on raw data → evaluate → add preprocessing only in production."]], "answers": ["B"], "multiple": false, "explanation": "<p>This combines the lecture's two big rules: <strong>split first</strong> (no leakage) and <strong>reuse the training parameters</strong> (consistency) — including at deployment, which is why the fitted preprocessors are saved. A leaks. C re-learns parameters on test data. D creates a mismatch between training and production inputs.</p>"}, {"module": 2, "number": "D17", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>You must predict hourly restaurant sales from a raw <code>timestamp</code>. Which engineered feature set is most useful?</p>", "options": [["A", "The raw timestamp string only."], ["B", "<code>hour</code>, <code>day_of_week</code>, <code>is_weekend</code> and a public-holiday flag derived from the timestamp."], ["C", "A label-encoded version of the full timestamp string."], ["D", "The timestamp's character length."]], "answers": ["B"], "multiple": false, "explanation": "<p>Sales follow <strong>daily and weekly cycles and holidays</strong>. Derived parts expose those patterns directly — the lecture's weekend example, extended. A and C give a mostly unique value per row with no learnable pattern. D is meaningless.</p>"}, {"module": 2, "number": "D18", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>A new dataset arrives. Which plan should come <strong>before</strong> any modelling?</p>", "options": [["A", "Fit three models and keep whichever scores best."], ["B", "Drop every row with any missing value, then model."], ["C", "Scale every column, including the IDs, then inspect."], ["D", "<code>info()</code> for types and nulls, <code>describe()</code> for ranges and outliers, <code>duplicated()</code> checks, <code>value_counts()</code> on categories, and a histogram or box plot of key numeric columns."]], "answers": ["D"], "multiple": false, "explanation": "<p>\"Inspect before touching.\" This covers the lecture's data-quality checklist: missing values, wrong types, duplicates and extreme outliers, plus visualisation. A models blind. B destroys data before understanding it. C transforms meaningless columns.</p>"}, {"module": 2, "number": "X10", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": "Industry", "question": "<p>Six months after launch, a retrained model gives different results, and nobody can reproduce the original. Which practice set best prevents this?</p>", "options": [["A", "Keep only the final model file."], ["B", "Retrain on whatever data is in the database today."], ["C", "Record the experiment in a slide deck."], ["D", "Version the raw data snapshot, code, fitted preprocessing parameters, model and random seeds together, so any model can be rebuilt exactly."]], "answers": ["D"], "multiple": false, "explanation": "<p>Reproducibility needs <strong>every input</strong> that shaped the model, including the fitted preprocessing (the lecture's \"same parameters\" rule extended across time). A loses the preprocessing and the data. B silently changes the data. C isn't executable.</p>"}, {"module": 3, "number": "D1", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>A nominal feature has <strong>m = 5</strong> categories. How many columns do one-hot, dummy and effect coding produce?</p>", "options": [["A", "5, 4, 4"], ["B", "5, 5, 4"], ["C", "4, 4, 5"], ["D", "1, 4, 5"]], "answers": ["A"], "multiple": false, "explanation": "<p>One-hot uses <strong>m</strong> columns. Dummy coding drops a reference level, giving <strong>m − 1</strong>. Effect coding also uses <strong>m − 1</strong>, but codes the reference as −1s instead of 0s. D starts with label encoding's single column, which isn't one-hot.</p>"}, {"module": 3, "number": "D2", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>What restriction does the lecture give for the Box-Cox transformation?</p>", "options": [["A", "The feature must be categorical."], ["B", "The values must be integers."], ["C", "The feature must already be normally distributed."], ["D", "The values must be strictly positive (x &gt; 0)."]], "answers": ["D"], "multiple": false, "explanation": "<p>Box-Cox involves $x^\\lambda$ and $\\log x$, which need <strong>x &gt; 0</strong>. A and B are false. C has it backwards — Box-Cox is used to make data <em>more</em> normal-like.</p>"}, {"module": 3, "number": "D3", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>Which pandas function creates bins that each hold <strong>roughly the same number of observations</strong>?</p>", "options": [["A", "<code>pd.qcut</code>"], ["B", "<code>pd.cut</code>"], ["C", "<code>pd.get_dummies</code>"], ["D", "<code>np.log1p</code>"]], "answers": ["A"], "multiple": false, "explanation": "<p><code>qcut</code> makes <strong>quantile</strong> bins (equal counts). <code>cut</code> makes bins from given or equal-width edges. <code>get_dummies</code> one-hot encodes, and <code>log1p</code> is a transform.</p>"}, {"module": 3, "number": "D4", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>For \"has this user shown any interest in the song?\", why can binarising <code>listen_count</code> beat keeping the raw count?</p>", "options": [["A", "Binary features always train faster, which improves accuracy."], ["B", "Raw counts cannot be stored as integers."], ["C", "The question is about <strong>presence</strong>: 0 → 1 matters a lot, while 37 → 38 is mostly noise, so the raw magnitude adds variation the target doesn't depend on."], ["D", "Binarisation removes all users who never listened."]], "answers": ["C"], "multiple": false, "explanation": "<p>Feature engineering means representing what the <strong>problem</strong> needs. If the target depends on whether a user listened at all, the magnitude is irrelevant and only adds noise. A confuses speed with accuracy. B is false. D is wrong — zero-listen users stay as 0.</p>"}, {"module": 3, "number": "D5", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>Why does the lecture call feature engineering <strong>iterative</strong>?</p>", "options": [["A", "Because every feature must be recomputed once per epoch."], ["B", "Because model errors reveal what the representation is missing (e.g. weekend mistakes suggest an <code>is_weekend</code> feature), so you engineer, train, evaluate and engineer again."], ["C", "Because polynomial features must be added one degree at a time."], ["D", "Because CRISP-DM forbids changing features after modelling."]], "answers": ["B"], "multiple": false, "explanation": "<p>The loop is <strong>engineer → train → evaluate → new feature ideas</strong>. Evaluation tells you where the representation fails. A and C are mechanical misreadings, and D is the opposite of CRISP-DM's iterative arrows.</p>"}, {"module": 3, "number": "D6", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>For a linear model on incomes ranging from RM25,000 to RM1,000,000, why can a log transform help?</p>", "options": [["A", "It compresses large values far more than small ones, so a few extreme incomes stop dominating the fit, while the order is preserved."], ["B", "It deletes outliers from the dataset."], ["C", "It guarantees a perfectly normal distribution."], ["D", "It lets the model use zero and negative incomes."]], "answers": ["A"], "multiple": false, "explanation": "<p>$\\log_{10}$ maps 10 → 1, 1,000 → 3 and 1,000,000 → 6, which pulls the long right tail inward. Rows aren't deleted (B). Normality isn't guaranteed (C). And log is <strong>undefined</strong> at zero and below (D) — that is why <code>log1p</code> or Yeo-Johnson exist.</p>"}, {"module": 3, "number": "X5", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": "PhD", "question": "<p>In \"entity embeddings\", a neural network learns a dense vector for each category (for example each of 5,000 stores) during training. What advantage do they have over one-hot encoding?</p>", "options": [["A", "Similar categories can learn nearby vectors, sharing statistical strength in a low-dimensional space, instead of 5,000 independent, equally distant columns."], ["B", "They need no training data."], ["C", "They guarantee an ordinal order."], ["D", "They remove the need for a train/test split."]], "answers": ["A"], "multiple": false, "explanation": "<p>One-hot makes every category <strong>equally different</strong> from every other — the same limitation Lecture 4 shows for words. Learned embeddings place behaviourally similar stores close together, which helps rare categories. It is the categorical version of word embeddings. B, C and D are false.</p>"}, {"module": 3, "number": "D7", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p><code>PolynomialFeatures(degree=2, include_bias=False)</code> is applied to <strong>3</strong> features. How many output columns?</p>", "options": [["A", "6"], ["B", "12"], ["C", "10"], ["D", "9"]], "answers": ["D"], "multiple": false, "explanation": "<p>3 originals + 3 squares + 3 pairwise products = <strong>9</strong>. In general this is $\\binom{n+d}{d} - 1 = \\binom{5}{2} - 1 = 9$. C counts the bias column. A forgets the cross terms. This growth is the lecture's \"feature explosion\".</p>"}, {"module": 3, "number": "D8", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p><code>pd.get_dummies(df[\"genre\"], drop_first=True)</code> is applied to the categories Action, Adventure and Sports. What does a row with genre <strong>Action</strong> become?</p>", "options": [["A", "Adventure = 0, Sports = 0"], ["B", "Action = 1, Adventure = 0"], ["C", "Adventure = −1, Sports = −1"], ["D", "Adventure = 1, Sports = 0"]], "answers": ["A"], "multiple": false, "explanation": "<p><code>drop_first</code> removes the first category in sorted order, <strong>Action</strong>, which becomes the reference represented by all zeros. C is effect coding. B keeps the dropped column. D is how Adventure is encoded.</p>"}, {"module": 3, "number": "D9", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>Box-Cox selects <strong>λ = 0</strong> for an income feature. Which transform is applied?</p>", "options": [["A", "Reciprocal, 1/x"], ["B", "Natural log, ln(x)"], ["C", "Square root"], ["D", "No change"]], "answers": ["B"], "multiple": false, "explanation": "<p>Box-Cox is $(x^\\lambda - 1)/\\lambda$ for $\\lambda \\ne 0$ and $\\ln x$ at $\\lambda = 0$. That is why the lecture says Box-Cox can <strong>act like a log transform</strong>. λ = 0.5 gives a square-root-like transform, λ = −1 a reciprocal-like one, and λ = 1 only shifts the values by 1.</p>"}, {"module": 3, "number": "X2", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Master's", "question": "<p>100 distinct categories are hashed uniformly into 1,000 buckets. Approximately what is the probability that <strong>at least one</strong> pair collides?</p>", "options": [["A", "About 0.10"], ["B", "About 0.50"], ["C", "0"], ["D", "About 0.99"]], "answers": ["D"], "multiple": false, "explanation": "<p>This is the birthday problem: $P(\\text{no collision}) = \\prod_{i=0}^{99}(1 - i/1000) \\approx e^{-100 \\cdot 99 / 2000} \\approx 0.006$, so $P(\\ge 1) \\approx 0.994$. On average about $\\binom{100}{2}/1000 \\approx 5$ pairs collide. Collisions are near-certain long before buckets run out, which is the lecture's trade-off made concrete.</p>"}, {"module": 3, "number": "X6", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Coding", "question": "<p>How many columns does this produce?</p>\n<pre><code class=\"language-python\">from sklearn.preprocessing import PolynomialFeatures\nPolynomialFeatures(degree=3, include_bias=False).fit_transform(X)  # X has 10 columns\n</code></pre>", "options": [["A", "30"], ["B", "1,000"], ["C", "285"], ["D", "165"]], "answers": ["C"], "multiple": false, "explanation": "<p>The number of monomials of degree 1–3 in 10 variables is $\\binom{10+3}{3} - 1 = 286 - 1 = 285$. A counts only powers of single variables. B is $10^3$, which counts ordered products. D is wrong because degree-1 and degree-2 terms are also included. Going from 10 to 285 features is the lecture's <strong>feature explosion</strong>.</p>"}, {"module": 3, "number": "D10", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>A right-skewed income feature is binned two ways:</p>\n<table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Counts in the 4 bins</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Fixed-width</td>\n<td>235 · 48 · 14 · 3</td>\n</tr>\n<tr>\n<td>Quantile</td>\n<td>75 · 75 · 75 · 75</td>\n</tr>\n</tbody>\n</table>\n<p>Which reading is most accurate?</p>", "options": [["A", "Fixed-width is better, because the counts reveal the skew."], ["B", "Both are equivalent, because both have four bins."], ["C", "Fixed-width spends most bins on the sparse tail; quantile bins give each bin enough data, at the cost of uneven, data-dependent boundaries."], ["D", "Quantile binning lost information, because the counts are identical."]], "answers": ["C"], "multiple": false, "explanation": "<p>That is the lecture's exact trade-off. Equal widths leave tail bins nearly empty on skewed data. Quantile bins <strong>adapt</strong> to the distribution but their edges are no longer round, meaningful numbers. A confuses describing the data with representing it usefully. D misreads equal counts as lost information.</p>"}, {"module": 3, "number": "D11", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>Training data has colours {Red, Blue, Green}; the test batch has {Red, Purple}. You call <code>pd.get_dummies</code> <strong>separately</strong> on each. What goes wrong?</p>", "options": [["A", "Nothing — get_dummies always returns the same columns."], ["B", "Purple is automatically mapped to Red."], ["C", "The training data gets an extra Purple column."], ["D", "The column sets differ (the test set has <code>Purple</code> and lacks <code>Blue</code> and <code>Green</code>), so the model receives a mismatched feature matrix."]], "answers": ["D"], "multiple": false, "explanation": "<p>Each call learns categories from <strong>its own</strong> data. That is the lecture's critical train-vs-unseen rule. Fit an encoder on training data and reuse it, for example <code>OneHotEncoder(handle_unknown=\"ignore\")</code>, which maps unseen Purple to all zeros. A, B and C are false.</p>"}, {"module": 3, "number": "D12", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>A linear model predicts battle wins from Attack and Defense. It underpredicts when <strong>both</strong> are high and overpredicts when only one is high. What does this pattern suggest?</p>", "options": [["A", "The two features interact; add Attack × Defense."], ["B", "The features need min-max scaling."], ["C", "The model is overfitting."], ["D", "Attack should be binarised."]], "answers": ["A"], "multiple": false, "explanation": "<p>An additive model gives each feature a fixed contribution. Errors that depend on the <strong>combination</strong> are the signature of an interaction, which is the lecture's Pokémon example. Scaling (B) doesn't change what an additive model can represent. C doesn't match a systematic pattern. D throws information away.</p>"}, {"module": 3, "number": "X1", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Hackathon", "question": "<p>In a hackathon, you replace <code>merchant_id</code> with the <strong>mean fraud rate of that merchant over the whole training set</strong>. CV shows 0.98, the leaderboard 0.71. Why?</p>", "options": [["A", "Merchant IDs have too few categories."], ["B", "Target encoding must use the median."], ["C", "Each row's encoding included its own label, which leaked the target; for rare merchants it nearly equals the label. Use out-of-fold target encoding with smoothing."], ["D", "The leaderboard uses a different metric."]], "answers": ["C"], "multiple": false, "explanation": "<p>Target encoding computed on the same rows it encodes <strong>contains the answer</strong>. Out-of-fold encoding computes each row's value from other folds only, and smoothing $\\frac{n\\bar y + m\\,p}{n+m}$ pulls rare categories toward the prior $p$. It's the lecture's \"fit only on what you're allowed to see\" rule applied <em>within</em> the training data.</p>"}, {"module": 3, "number": "X7", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Industry", "question": "<p>Quantile income bins were fitted on last year's training data. This year, nominal incomes rise about 30%, and most customers now fall into the top bin. What is happening?</p>", "options": [["A", "Quantile bins re-adapt automatically at prediction time."], ["B", "Fitted bin edges are fixed parameters. Under distribution shift they stop splitting the population evenly, so drift must be monitored and the bins (and model) refitted."], ["C", "The bins are fine; only the model is wrong."], ["D", "Fixed-width bins would be immune."]], "answers": ["B"], "multiple": false, "explanation": "<p>Quantile edges are <strong>learned from training data</strong> and then reused, which is the consistency rule. When the distribution shifts, reused edges no longer represent quartiles. A is the trap — transform doesn't refit. D is false; any fixed edges suffer under shift.</p>"}, {"module": 3, "number": "X10", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "PhD", "question": "<p>A true risk relationship is smooth in age. An analyst bins age into 5 bins before fitting. What is the main statistical cost?</p>", "options": [["A", "None — binning always reduces variance with no downside."], ["B", "Within-bin variation is discarded, and the model becomes a step function with artificial jumps at the bin edges, losing information and power."], ["C", "It increases the number of features exponentially."], ["D", "It makes the feature nominal, so ordering is lost."]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture says binning trades precision for abstraction. The extension is the <em>price</em>: a step function forces people at 39.9 and 40.1 into different risk levels, and ignores the gradient inside each bin. Binning helps when the boundaries are meaningful (D15) or the relationship really is stepwise. A is false. C confuses binning with polynomial expansion. D is false — bins can stay ordinal.</p>"}, {"module": 3, "number": "X12", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Master's", "question": "<p>The true target is $\\text{Attack} \\times \\text{Defense}$. Which model <strong>cannot</strong> capture it without an explicit interaction feature?</p>", "options": [["A", "A deep decision tree."], ["B", "A linear regression on Attack and Defense only."], ["C", "A neural network with hidden layers."], ["D", "A gradient-boosted ensemble of depth-6 trees."]], "answers": ["B"], "multiple": false, "explanation": "<p>A linear model is <strong>additive</strong> in its inputs, so it can't represent a product unless you engineer the column — which is exactly why the lecture creates Attack × Defense. Trees with depth ≥ 2 and neural networks can learn interactions themselves (A, C, D). An ensemble of depth-1 stumps, by contrast, would also be additive.</p>"}, {"module": 3, "number": "D13", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>Education has the levels Primary &lt; Secondary &lt; Diploma &lt; Degree. For a linear model, which encoding is most defensible?</p>", "options": [["A", "One-hot, because label-style encoding is always wrong."], ["B", "Ordinal mapping (1–4) in the domain order, because the order is real and one column carries it."], ["C", "Alphabetical label encoding, because it is automatic."], ["D", "Feature hashing."]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture's rule is to ask <strong>nominal or ordinal?</strong> first. For genuinely ordered levels, a domain-defined mapping keeps the order. A over-applies the nominal rule; one-hot would also work but discards the order the model could use. C would order Degree &lt; Diploma &lt; Primary &lt; Secondary, which is meaningless. D is for high cardinality.</p>"}, {"module": 3, "number": "D14", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>A logistic regression must use <code>product_id</code> with 250,000 distinct values on a memory-constrained server. Which choice is most defensible?</p>", "options": [["A", "One-hot encoding, because it is exact."], ["B", "Label encoding, because it uses one column."], ["C", "Feature hashing into a fixed number of buckets, accepting some collisions."], ["D", "Drop the feature, because high-cardinality columns are useless."]], "answers": ["C"], "multiple": false, "explanation": "<p>The lecture introduces hashing for <strong>thousands of categories</strong>: a fixed output size at the cost of collisions. A creates 250k columns. B imposes a false order on IDs, which a linear model treats as magnitude. D may discard strong signal.</p>"}, {"module": 3, "number": "D15", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>Insurance regulations define the age bands 18–25, 26–40, 41–65 and 66+, and premiums must be explained by band. Which binning fits best?</p>", "options": [["A", "Custom bins matching the regulatory bands."], ["B", "Quantile bins, because they balance the counts."], ["C", "Fixed-width 10-year bins."], ["D", "No binning, because exact age is always better."]], "answers": ["A"], "multiple": false, "explanation": "<p>The lecture's <strong>custom binning</strong> principle: domain knowledge beats arbitrary mathematics when boundaries carry meaning. Quantile edges (B) would shift with the data and not match the regulation. C ignores the mandated bands. D conflicts with the explanation requirement.</p>"}, {"module": 3, "number": "X3", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Master's", "question": "<p><code>monthly_profit</code> is right-skewed but contains zeros and negative values. Which transformation is most appropriate?</p>", "options": [["A", "Box-Cox, because it chooses λ automatically."], ["B", "Yeo-Johnson, a power-transform family defined for all real values, with λ chosen by maximum likelihood."], ["C", "Plain log transform."], ["D", "Binarisation, because skewed data must be binned."]], "answers": ["B"], "multiple": false, "explanation": "<p>Box-Cox requires <strong>x &gt; 0</strong>, which is the lecture's stated restriction, so A fails. Log fails at zero and below (C). Yeo-Johnson extends the Box-Cox idea to zero and negative values. D throws away magnitude unnecessarily.</p>"}, {"module": 3, "number": "X4", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Industry", "question": "<p>Label-encoding a nominal feature is \"dangerous\" in the lecture. How dangerous is it for a <strong>gradient-boosted tree</strong> compared with a <strong>linear</strong> model?</p>", "options": [["A", "Equally harmful for both, because both read the codes as magnitudes."], ["B", "Harmless for both."], ["C", "Much less harmful for trees: they split on thresholds and can isolate categories with several splits, though arbitrary codes can need more splits. A linear model treats the codes as true magnitudes."], ["D", "More harmful for trees than for linear models."]], "answers": ["C"], "multiple": false, "explanation": "<p>The danger is the <strong>implied magnitude and order</strong>. Linear models multiply the code by a weight, so the danger is direct. Trees only use order to place thresholds, so arbitrary codes cost extra splits but don't impose a linear effect. That's why many boosting libraries accept categorical codes directly. The lecture's rule is still the safe default for linear and distance-based models.</p>"}, {"module": 3, "number": "X8", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Master's", "question": "<p>A ridge regression (L2-regularised, with an intercept) uses <strong>full</strong> one-hot encoding of a 4-level feature, without dropping a column. Which statement is most accurate?</p>", "options": [["A", "It fails because the matrix is singular."], ["B", "It is acceptable: regularisation makes the system solvable despite the collinearity, and all levels are treated symmetrically. Ordinary least squares without regularisation is where dummy coding matters most."], ["C", "Effect coding is required for any regularised model."], ["D", "Dummy coding must always be used, regardless of the model."]], "answers": ["B"], "multiple": false, "explanation": "<p>The dummy-variable trap is <strong>perfect collinearity</strong> between the one-hot columns and the intercept. Unregularised OLS then has no unique solution, which is why the lecture motivates dummy coding. An L2 penalty adds $\\lambda I$, making the system invertible, so full one-hot is common with regularised models. A ignores the penalty. C and D are overgeneralisations.</p>"}, {"module": 3, "number": "D16", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>A dataset has <code>listen_count</code> (only presence matters), <code>income</code> (strongly right-skewed), <code>city</code> (30 unordered values) and <code>size</code> (S &lt; M &lt; L). Which feature design is best?</p>", "options": [["A", "Log <code>listen_count</code>; binarise income; ordinal-map city; one-hot size."], ["B", "Leave everything raw and let the model sort it out."], ["C", "Binarise <code>listen_count</code>; log-transform <code>income</code>; one-hot <code>city</code>; ordinal-map <code>size</code>."], ["D", "One-hot every column, including income."]], "answers": ["C"], "multiple": false, "explanation": "<p>Each technique matches each column's nature — presence → <strong>binarise</strong>; skew → <strong>log</strong>; nominal → <strong>one-hot</strong>; ordered → <strong>ordinal mapping</strong>. A mismatches every pair. B ignores the point of the lecture. D one-hots a continuous variable, creating thousands of columns.</p>"}, {"module": 3, "number": "D17", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>You want to know whether a new interaction feature truly helps. Which experiment is best?</p>", "options": [["A", "Add it and check whether <strong>training</strong> accuracy improves."], ["B", "Add it, retrain, and compare performance on held-out validation data against the same model without it; keep it only if it generalises better."], ["C", "Add it only if it has the largest coefficient."], ["D", "Add every possible interaction at once and keep the model with the highest training score."]], "answers": ["B"], "multiple": false, "explanation": "<p>This is the iterative loop, judged on <strong>unseen data</strong>. A and D reward fitting more, which a new feature almost always does on training data — the overfitting trap. C confuses coefficient size, which depends on scale, with predictive value.</p>"}, {"module": 3, "number": "D18", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>Design categorical encoding that won't break when production sends a category never seen in training.</p>", "options": [["A", "Call <code>pd.get_dummies</code> on each production batch."], ["B", "Fit <code>OneHotEncoder(handle_unknown=\"ignore\")</code> on training data, save it with the model, and only <code>transform</code> test and production data."], ["C", "Refit the encoder on each production batch so it always knows every category."], ["D", "Label-encode in production, because unseen categories get the next integer."]], "answers": ["B"], "multiple": false, "explanation": "<p>Fit once on training data, reuse everywhere — the lecture's critical rule, plus explicit handling of unseen values. A and C re-learn the categories, so the columns differ from training. D gives an unseen category a number the model never learned, with a fake order.</p>"}, {"module": 3, "number": "X9", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": "Industry", "question": "<p>A regulator requires that, all else equal, a <strong>higher income can never lower</strong> the predicted credit approval. Which design meets this?</p>", "options": [["A", "Log-transform income; that guarantees monotonicity."], ["B", "Quantile-bin income into 10 bins."], ["C", "Drop income from the model."], ["D", "Train a gradient-boosted model with a monotonic (increasing) constraint on income, and verify it with partial-dependence checks."]], "answers": ["D"], "multiple": false, "explanation": "<p>Monotonic constraints restrict every tree split so the effect of income can only increase, which enforces domain knowledge directly. A keeps the order of the feature, but the <em>model</em> can still learn a non-monotonic response. B can produce non-monotonic bin effects. C loses predictive power. It's feature engineering's \"domain knowledge\" principle turned into a model constraint.</p>"}, {"module": 3, "number": "X11", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": "Hackathon", "question": "<p><code>device_model</code> has 3,000 values; 2,600 of them appear fewer than 10 times, and the test set will contain unseen models. Which plan is best?</p>", "options": [["A", "One-hot all 3,000 values."], ["B", "Drop the rows with rare devices."], ["C", "On the training data, map categories with fewer than 10 occurrences to <code>\"Other\"</code>; fit the encoder on that; at prediction time, map unseen values to <code>\"Other\"</code> as well."], ["D", "Label-encode in order of first appearance."]], "answers": ["C"], "multiple": false, "explanation": "<p>Grouping rare levels shrinks the number of columns, reduces overfitting on tiny categories, and gives unseen values a safe home. Learning the threshold from <strong>train only</strong> keeps it consistent. A explodes in width and overfits. B deletes data and fails on unseen values anyway. D imposes a false order.</p>"}, {"module": 4, "number": "D1", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>Which order matches the lecture's text-preprocessing pipeline?</p>", "options": [["A", "Tokenise → lowercase → remove special characters → remove stopwords → stem / lemmatise"], ["B", "Stem → tokenise → lowercase → remove stopwords → remove special characters"], ["C", "Remove stopwords → tokenise → stem → lowercase → remove special characters"], ["D", "Lowercase → stem → tokenise → remove stopwords → TF-IDF"]], "answers": ["A"], "multiple": false, "explanation": "<p>The slides list <strong>tokenisation → lowercasing → special characters → stopwords → stemming / lemmatisation</strong>. B stems before splitting into words. C removes stopwords before there are tokens. D mixes in feature extraction (TF-IDF), which comes <em>after</em> cleaning.</p>"}, {"module": 4, "number": "D2", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>In Word2Vec, what does the CBOW architecture predict?</p>", "options": [["A", "The surrounding context words from the target word."], ["B", "The document's topic mixture."], ["C", "The TF-IDF weight of each word."], ["D", "The target word from its surrounding context words."]], "answers": ["D"], "multiple": false, "explanation": "<p><strong>CBOW: context → target.</strong> A describes Skip-gram (target → context). B is LDA. C is unrelated.</p>"}, {"module": 4, "number": "D3", "set": "difficult", "bloom": "Remember", "bloom_rank": 1, "ext": null, "question": "<p>Which grayscale formula does the lecture use?</p>", "options": [["A", "$Y = (R + G + B)/3$"], ["B", "$Y = 0.2125R + 0.7154G + 0.0721B$"], ["C", "$Y = 0.7154R + 0.2125G + 0.0721B$"], ["D", "$Y = \\max(R, G, B)$"]], "answers": ["B"], "multiple": false, "explanation": "<p>Green gets the largest weight (≈ 72%) because human eyes are most sensitive to it. C swaps the red and green weights. A is a plain average. D is the \"value\" channel of HSV, not luminance.</p>"}, {"module": 4, "number": "D4", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>Using the lecture's $\\text{IDF}(t) = \\log(N/\\text{df}(t))$, why does a word that appears in <strong>every</strong> document end up with zero weight?</p>", "options": [["A", "Because stopwords are always deleted first."], ["B", "Because TF is zero for very common words."], ["C", "Because $N/\\text{df} = 1$ and $\\log 1 = 0$: a word found everywhere cannot distinguish one document from another."], ["D", "Because IDF is only defined for rare words."]], "answers": ["C"], "multiple": false, "explanation": "<p>IDF measures how <strong>distinctive</strong> a term is across the corpus. A term in all N documents has no discriminating power, so its weight vanishes, however frequent it is within a document. A confuses cleaning with weighting. B is false — TF can be high. D is false.</p>"}, {"module": 4, "number": "D5", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>Why does the lecture prefer cosine similarity to raw Euclidean distance for comparing documents?</p>", "options": [["A", "Cosine compares the <strong>direction</strong> of count vectors, so a long document and a short one with the same word proportions count as similar."], ["B", "Cosine is faster to compute."], ["C", "Euclidean distance cannot be computed on sparse vectors."], ["D", "Cosine ignores which words appear."]], "answers": ["A"], "multiple": false, "explanation": "<p>\"dog cat animal\" and \"dog dog cat cat animal animal\" point the <strong>same way</strong>, so cosine is 1, but they are far apart in Euclidean terms because one is twice as long. The difference is about meaning, not speed (B). C and D are false.</p>"}, {"module": 4, "number": "D6", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": null, "question": "<p>Logs come from servers in Kuala Lumpur (UTC+8) and London (UTC+0). Why convert to UTC <strong>before</strong> extracting <code>hour</code>?</p>", "options": [["A", "UTC timestamps use less memory."], ["B", "The same instant shows a different local hour on each server; extracting local hours would create fake 8-hour gaps and mismatched patterns."], ["C", "pandas cannot extract hours from local times."], ["D", "UTC removes weekends."]], "answers": ["B"], "multiple": false, "explanation": "<p>14:00 in KL and 06:00 in London can be the <strong>same moment</strong>. Features derived from unaligned clocks misrepresent behaviour — the lecture names this as one of its five common mistakes. A, C and D are false.</p>"}, {"module": 4, "number": "X4", "set": "difficult", "bloom": "Understand", "bloom_rank": 2, "ext": "PhD", "question": "<p>Levy &amp; Goldberg (2014) showed that skip-gram with negative sampling (SGNS), with $k$ negative samples, implicitly factorises which matrix?</p>", "options": [["A", "The raw word–document count matrix."], ["B", "The TF-IDF matrix."], ["C", "The word–context PMI matrix shifted by $\\log k$: $\\text{PMI}(w, c) - \\log k$."], ["D", "The identity matrix."]], "answers": ["C"], "multiple": false, "explanation": "<p>At the optimum, SGNS's dot products satisfy $\\vec w \\cdot \\vec c = \\text{PMI}(w, c) - \\log k$. So Word2Vec embeddings are a low-rank factorisation of co-occurrence statistics. That links the lecture's \"counts → meaning\" step formally: embeddings compress <em>context</em> counts, while BoW uses <em>document</em> counts.</p>"}, {"module": 4, "number": "D7", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p><code>CountVectorizer(ngram_range=(1, 2))</code> is applied to the single document <code>\"not good at all\"</code>, with no stopword removal. How many features does it produce?</p>", "options": [["A", "4"], ["B", "6"], ["C", "10"], ["D", "7"]], "answers": ["D"], "multiple": false, "explanation": "<p>4 unigrams (not, good, at, all) + 3 bigrams (not good, good at, at all) = <strong>7</strong>. A counts unigrams only. B and C miscount the bigrams. Keeping \"not good\" as one feature is the lecture's reason for using n-grams.</p>"}, {"module": 4, "number": "D8", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>What is the cosine similarity between $A = [1, 1, 0]$ and $B = [1, 0, 1]$?</p>", "options": [["A", "0.5"], ["B", "0"], ["C", "1"], ["D", "0.71"]], "answers": ["A"], "multiple": false, "explanation": "<p>$A \\cdot B = 1$ and $\\|A\\| = \\|B\\| = \\sqrt{2}$, so $\\cos\\theta = 1/2 = 0.5$: one shared term out of two each. B would need no shared terms; C identical directions. D ($1/\\sqrt{2}$) forgets to divide by the second vector's norm.</p>"}, {"module": 4, "number": "D9", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": null, "question": "<p>A 28 × 28 RGB image is flattened directly. If it is first converted to grayscale and then flattened, how many features are there in each case?</p>", "options": [["A", "784 and 2,352"], ["B", "2,352 and 784"], ["C", "2,352 and 2,352"], ["D", "84 and 28"]], "answers": ["B"], "multiple": false, "explanation": "<p>RGB: $28 \\times 28 \\times 3 = 2{,}352$. Grayscale reduces $(m, n, 3)$ to $(m, n)$, giving $28 \\times 28 = 784$, so grayscale cuts the dimension by 3×. A swaps the two. D sums rows instead of multiplying.</p>"}, {"module": 4, "number": "X1", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Coding", "question": "<p>scikit-learn's <code>TfidfVectorizer</code> (default <code>smooth_idf=True</code>) computes $\\text{idf}(t) = \\ln\\frac{1 + n}{1 + \\text{df}(t)} + 1$. With <strong>n = 4</strong> documents and a term in <strong>all 4</strong>, what is its idf?</p>", "options": [["A", "0"], ["B", "$\\ln 4 \\approx 1.386$"], ["C", "Undefined"], ["D", "1"]], "answers": ["D"], "multiple": false, "explanation": "<p>$\\ln(5/5) + 1 = 0 + 1 = \\mathbf{1}$. Unlike the lecture's plain $\\log(N/\\text{df})$, which gives 0 (A), sklearn adds <strong>+1</strong>, so ubiquitous terms keep a small weight, and the smoothing prevents division by zero. Always check the library's definition: hand-computed answers and sklearn output can differ.</p>"}, {"module": 4, "number": "X3", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Master's", "question": "<p>Two document vectors are <strong>L2-normalised</strong> and have cosine similarity 0.6. What is their squared Euclidean distance, and what does that imply?</p>", "options": [["A", "0.4; Euclidean and cosine rankings can disagree."], ["B", "0.8; for unit vectors, $\\|a - b\\|^2 = 2 - 2\\cos\\theta$, so ranking by Euclidean distance equals ranking by cosine."], ["C", "1.6; Euclidean is always larger."], ["D", "0.36; square the cosine."]], "answers": ["B"], "multiple": false, "explanation": "<p>For unit vectors, $\\|a-b\\|^2 = \\|a\\|^2 + \\|b\\|^2 - 2a\\cdot b = 2 - 2(0.6) = 0.8$. Distance is a monotone function of cosine, so after L2 normalisation (sklearn's TF-IDF default) the two give the <strong>same nearest neighbours</strong>. The lecture's \"use cosine\" advice is really about length; normalisation removes length.</p>"}, {"module": 4, "number": "X6", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Hackathon", "question": "<p>Hour of day is encoded as $(\\sin(2\\pi h/24), \\cos(2\\pi h/24))$. What is the Euclidean distance between hour 23 and hour 0, compared with the raw-hour distance?</p>", "options": [["A", "About 0.26 (vs 23 for raw hours)"], ["B", "23 in both encodings"], ["C", "2.0"], ["D", "0"]], "answers": ["A"], "multiple": false, "explanation": "<p>On the unit circle, adjacent hours are close: the distance is $2\\sin(\\pi/24) \\approx 0.261$, whereas raw integers put 23 and 0 maximally far apart. C (2.0) is the distance between hours 12 and 0. The lecture bins hour into Morning/Afternoon/Night; cyclical encoding keeps the continuity across midnight instead.</p>"}, {"module": 4, "number": "X8", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Coding", "question": "<p>A HOG descriptor uses a 64 × 128 image, 8 × 8-pixel cells, 2 × 2-cell blocks with a stride of 1 cell, and 9 orientation bins. How long is the feature vector?</p>", "options": [["A", "1,152"], ["B", "3,780"], ["C", "4,608"], ["D", "3,240"]], "answers": ["B"], "multiple": false, "explanation": "<p>Cells: 8 × 16. Block positions: (8 − 1) × (16 − 1) = 7 × 15 = 105. Each block holds 2 × 2 cells × 9 bins = 36 values, so 105 × 36 = <strong>3,780</strong> — the classic Dalal–Triggs pedestrian detector. A counts cells × bins without blocks. C uses 128 block positions.</p>"}, {"module": 4, "number": "X9", "set": "difficult", "bloom": "Apply", "bloom_rank": 3, "ext": "Master's", "question": "<p>What is the receptive field of one output unit after: 3 × 3 conv (stride 1) → 2 × 2 max-pool (stride 2) → 3 × 3 conv (stride 1)?</p>", "options": [["A", "8 × 8"], ["B", "7 × 7"], ["C", "6 × 6"], ["D", "9 × 9"]], "answers": ["A"], "multiple": false, "explanation": "<p>Use $r \\mathrel{+}= (k-1)\\cdot j$ and $j \\mathrel{*}= s$. Start: r = 1, j = 1. Conv3: r = 3. Pool2/stride 2: r = 3 + 1 = 4, j = 2. Conv3: r = 4 + 2 × 2 = <strong>8</strong>. B is three stacked 3 × 3 convs with no pooling. This is the mechanism behind \"early layers see edges, deeper layers see shapes\": each layer widens the area a unit sees.</p>"}, {"module": 4, "number": "D10", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>\"dog bites man\" and \"man bites dog\" produce <strong>identical</strong> Bag-of-Words vectors. Which change lets a model tell them apart?</p>", "options": [["A", "TF-IDF weighting."], ["B", "Lowercasing."], ["C", "Adding bigrams such as \"dog bites\" and \"bites man\"."], ["D", "Removing stopwords."]], "answers": ["C"], "multiple": false, "explanation": "<p>BoW throws away word order. Both sentences have the same counts, so any <strong>reweighting</strong> of those counts (A) stays identical. Bigrams keep local order: \"dog bites\" occurs in one sentence, \"bites dog\" in the other. B and D don't add order information.</p>"}, {"module": 4, "number": "D11", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>An algorithm returns, for each news article, something like <code>{sports: 0.7, politics: 0.3}</code>. Which method most likely produced it, and why?</p>", "options": [["A", "LDA topic modelling — each document is a mixture of topics."], ["B", "k-means document clustering — each document gets one cluster label."], ["C", "Bag of Words — it counts words."], ["D", "Word2Vec — it outputs word vectors."]], "answers": ["A"], "multiple": false, "explanation": "<p>Proportions across several topics are the signature of <strong>topic modelling</strong>: documents are mixtures. Clustering (B) assigns each document to one group. C and D produce feature vectors, not topic mixtures.</p>"}, {"module": 4, "number": "D12", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": null, "question": "<p>Image P is a photo of a cat. Image Q contains exactly the same pixel values, randomly shuffled. Which features still <strong>differ</strong> between them?</p>", "options": [["A", "The intensity histogram."], ["B", "Mean, variance, skewness and kurtosis."], ["C", "Edge maps and HOG descriptors."], ["D", "None — all features are identical."]], "answers": ["C"], "multiple": false, "explanation": "<p>Histograms and summary statistics depend only on <strong>which</strong> values occur, not <strong>where</strong>, so A and B are identical for P and Q. Edges and HOG measure intensity changes between neighbouring pixels: P has contours, Q is noise. That is the lecture's point that histograms lose spatial information.</p>"}, {"module": 4, "number": "X5", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Industry", "question": "<p>A word-level BoW model has never seen \"unhappiness\". A subword (BPE / WordPiece) tokeniser splits it into \"un\", \"happi\", \"ness\". Why does this help?</p>", "options": [["A", "It removes the word from the text."], ["B", "Rare and unseen words share pieces with known words, so the model still gets meaningful features instead of an out-of-vocabulary blank, and the vocabulary stays small."], ["C", "It turns text into images."], ["D", "It guarantees correct spelling."]], "answers": ["B"], "multiple": false, "explanation": "<p>Word-level vocabularies can't represent unseen words. Subwords <strong>compose</strong> them from frequent fragments (\"un-\" negation, \"-ness\" noun). It's a learned middle ground between characters and words, extending the lecture's tokenisation step. A, C and D are false.</p>"}, {"module": 4, "number": "X7", "set": "difficult", "bloom": "Analyze", "bloom_rank": 4, "ext": "Industry", "question": "<p>An hourly demand series stored in <strong>London local time</strong> shows one missing hour in late March and a doubled hour in late October. What is the cause and the fix?</p>", "options": [["A", "Sensor failure; interpolate both."], ["B", "Leap seconds; ignore them."], ["C", "A pandas bug; upgrade the library."], ["D", "Daylight-saving transitions: one local hour doesn't exist in spring and one repeats in autumn. Store and aggregate in UTC, and convert to local time only for display or local-hour features."]], "answers": ["D"], "multiple": false, "explanation": "<p>On the spring change, clocks jump from 01:00 to 02:00, so that hour never happens; in autumn, 01:00–01:59 happens twice. Local wall-clock time isn't a continuous axis. The lecture's \"normalise to UTC\" rule fixes it. A papers over the problem and corrupts the data. B and C are wrong.</p>"}, {"module": 4, "number": "D13", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>A legal search engine shows the matched normalised terms to lawyers, so they must be real words (\"studies\" → \"study\", never \"studi\"). Which normalisation is best?</p>", "options": [["A", "Stemming, because it is faster."], ["B", "Lemmatisation, because it uses vocabulary and morphology to return valid dictionary forms."], ["C", "No normalisation, because legal text is precise."], ["D", "Remove all words longer than 6 letters."]], "answers": ["B"], "multiple": false, "explanation": "<p>The lecture contrasts <strong>heuristic</strong> stemming, which may produce non-words, with <strong>linguistic</strong> lemmatisation, which returns canonical forms. The requirement for real words decides it. A trades correctness for speed. C loses the matches between word forms. D is nonsense.</p>"}, {"module": 4, "number": "D14", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>For a food-delivery demand model, which timestamp representation is most defensible?</p>", "options": [["A", "Raw epoch seconds only."], ["B", "The timestamp as a label-encoded string."], ["C", "Nothing — timestamps leak information."], ["D", "<code>hour</code>, <code>day_of_week</code>, <code>is_weekend</code> and a time-of-day bin from UTC-aligned times, plus elapsed-time features where needed."]], "answers": ["D"], "multiple": false, "explanation": "<p>Demand follows <strong>daily and weekly cycles</strong>. Extracted parts expose them directly — the lecture's food-delivery example. A is monotonically increasing and hides the cycles. B is effectively a unique ID per row. C is false — timestamps are only a problem when they reveal the future.</p>"}, {"module": 4, "number": "D15", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": null, "question": "<p>You have 500 labelled images and limited compute. Which approach is most reasonable <strong>within the lecture's toolkit</strong>?</p>", "options": [["A", "Extract HOG or edge features and train a classical classifier."], ["B", "Train a deep CNN from scratch, because CNNs always beat hand-crafted features."], ["C", "Flatten raw pixels and use k-NN, because it needs no training."], ["D", "Use only intensity histograms, because they are fastest."]], "answers": ["A"], "multiple": false, "explanation": "<p>CNNs learn features automatically, but from-scratch training on 500 images is very likely to <strong>overfit</strong> (Lecture 1). Hand-crafted descriptors encode useful shape priors cheaply. C suffers from high dimensionality and the loss of spatial structure. D throws away all shape information.</p>"}, {"module": 4, "number": "X2", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Industry", "question": "<p>Search engines often prefer <strong>BM25</strong> to plain TF-IDF. Which statement best explains why?</p>", "options": [["A", "BM25 saturates term frequency (the 20th \"refund\" adds little over the 5th) and normalises for document length, so long, repetitive documents don't win just by repetition."], ["B", "BM25 ignores rare words."], ["C", "BM25 needs labelled training data."], ["D", "BM25 is TF-IDF without the IDF term."]], "answers": ["A"], "multiple": false, "explanation": "<p>BM25 keeps IDF's distinctiveness idea (so D is false) but adds a <strong>saturating</strong> TF curve controlled by $k_1$ and a <strong>length normalisation</strong> controlled by $b$. That fixes the two weaknesses of raw-count TF that follow from the lecture's \"problem with raw word counts\". B and C are false; BM25 is unsupervised.</p>"}, {"module": 4, "number": "X10", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "PhD", "question": "<p>Which statement about CNNs and translation is most accurate?</p>", "options": [["A", "CNNs are perfectly translation-invariant at every layer."], ["B", "Convolution is translation-<strong>equivariant</strong> (shift the input, the feature map shifts); pooling adds only limited local invariance, and striding/aliasing can make outputs change under small shifts."], ["C", "CNNs have no relationship to translation."], ["D", "Flattening pixels gives better translation invariance than convolution."]], "answers": ["B"], "multiple": false, "explanation": "<p>Shared kernels make convolution equivariant. Invariance comes only partly, from pooling and global aggregation, and downsampling breaks exact shift-invariance — a known source of brittleness. It refines the lecture's point that flattening destroys spatial structure (D is backwards).</p>"}, {"module": 4, "number": "X12", "set": "difficult", "bloom": "Evaluate", "bloom_rank": 5, "ext": "Postdoc", "question": "<p>You have 500 labelled medical images. Option 1: train a CNN from scratch. Option 2: extract frozen embeddings from a large self-supervised or contrastively pre-trained image model (e.g. CLIP-style) and train a linear classifier (\"linear probe\"). Which assessment is most defensible?</p>", "options": [["A", "Option 1 is always better, because task-specific training beats pre-training."], ["B", "Both are equivalent, because 500 images is enough for any method."], ["C", "Option 2 usually generalises better with few labels, because pre-trained representations encode general visual structure. But you must check for domain shift (natural vs medical images) and validate on held-out patients; fine-tuning or domain-specific pre-training may still be needed."], ["D", "Option 2 needs no validation, because the model is pre-trained."]], "answers": ["C"], "multiple": false, "explanation": "<p>This extends the lecture's arc from hand-crafted features (HOG) to <em>learned</em> features (CNNs) and then to <em>transferred</em> representations. With few labels, reusing representations reduces variance (Lecture 1). Domain shift is the key risk, so representativeness still matters. A and B ignore sample-size effects. D ignores evaluation entirely.</p>"}, {"module": 4, "number": "D16", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>Design a spam-filter text representation where \"not free\" must differ from \"free\", and generic words currently dominate.</p>", "options": [["A", "Remove all stopwords, including \"not\"; use unigram counts."], ["B", "Lowercase and tokenise; keep negations; use unigrams + bigrams; weight with TF-IDF fitted on the training emails only."], ["C", "Stem aggressively and use raw counts."], ["D", "Use one-hot document IDs."]], "answers": ["B"], "multiple": false, "explanation": "<p>Bigrams keep \"not free\"; keeping negations stops cleaning from deleting the signal; <strong>TF-IDF</strong> fixes the dominance of generic words; and fitting on train only avoids leakage. A deletes the negation the task depends on. C leaves both problems unsolved. D has no textual content.</p>"}, {"module": 4, "number": "D17", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>Equipment failure data has <code>machine_type</code>, <code>temperature</code> (noisy decimals), <code>maintenance_note</code> (text), <code>timestamp</code> (several sites) and an inspection image. Which design is best?</p>", "options": [["A", "Label-encode every column, then train a single model."], ["B", "Concatenate everything into one string and use TF-IDF."], ["C", "Split first; then, fitted on train only: one-hot <code>machine_type</code>; round or bin <code>temperature</code>; TF-IDF the notes; convert timestamps to UTC and extract parts; image → edges/HOG or CNN features; combine and train."], ["D", "Use only the image, because CNNs learn everything."]], "answers": ["C"], "multiple": false, "explanation": "<p>That's the lecture's <strong>\"one machine, five representations\"</strong> with the pipeline rule: split first, fit on train. A imposes a false order on machine types and ignores the text and image structure. B destroys numeric meaning. D discards cheap, highly informative structured signals.</p>"}, {"module": 4, "number": "D18", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": null, "question": "<p>Design a \"find similar documents\" feature for 50,000 support tickets.</p>", "options": [["A", "Fit TF-IDF on the corpus, represent the query with the same vectoriser, rank tickets by cosine similarity, and return the top k."], ["B", "Rank by Euclidean distance between raw word-count vectors."], ["C", "Cluster tickets with k-means and return a random ticket from the query's cluster."], ["D", "Compare ticket lengths."]], "answers": ["A"], "multiple": false, "explanation": "<p>TF-IDF down-weights generic words, and cosine ignores document length — the lecture's exact combination for <strong>document similarity</strong>. B favours tickets of similar length and lets common words dominate. C gives coarse, unranked results. D ignores content.</p>"}, {"module": 4, "number": "X11", "set": "difficult", "bloom": "Create", "bloom_rank": 6, "ext": "Industry", "question": "<p>A team augmented 1,000 images ×10 with flips and crops, then randomly split the 10,000 into train and test. Validation accuracy is 99%. Which protocol is correct?</p>", "options": [["A", "Augment, then split — more test images make evaluation more reliable."], ["B", "Augment only the test set."], ["C", "Don't augment at all, ever."], ["D", "Split the original images first (grouped by source image), then augment <strong>only</strong> the training set; evaluate on untouched originals."]], "answers": ["D"], "multiple": false, "explanation": "<p>Augmented copies of one photo are near-duplicates. Splitting after augmentation puts siblings in both sets — the lecture's duplicate-leakage and split-first rule for images. A causes the inflated 99%. B and C misunderstand augmentation's purpose, which is more training variety.</p>"}];
